window.PSW_DATA = {"workflows":{"registration":{"label":"Registration","purpose":"Process a pending Portal registration from Ivanti intake through RAC decision and ticket closure.","systems":["Ivanti","RAC","Florida Bar website when applicable"],"required":["incidentNumber","customerName","emailValue","phoneValue","filerRole","issueSummary"],"optional":["addressValue","barNumber","usernameValue","dateTime"],"groups":[{"name":"Claim and classify the Ivanti ticket","items":[{"text":"Set the queue to Portal Service Desk All Open Tickets.","required":true,"note":""},{"text":"Open the incident and review the complete description, email, attachments, and ticket history.","required":true,"note":""},{"text":"Assign the incident to yourself.","required":true,"note":""},{"text":"Select the filer role shown or requested on the ticket.","required":true,"note":""},{"text":"Save immediately after taking ownership and selecting the filer role.","required":true,"note":""},{"text":"Update the dropdowns and fields beneath Description.","required":true,"note":""},{"text":"Change Summary to Registration – [filer name].","required":true,"note":""},{"text":"Save the updated incident.","required":true,"note":""}]},{"name":"Create or update the Ivanti customer","items":[{"text":"Search for an existing customer before creating a new customer record.","required":true,"note":""},{"text":"Create a new customer or update the correct existing customer.","required":true,"note":""},{"text":"Enter or verify the filer’s name, email address, and telephone number.","required":true,"note":""},{"text":"Set Organizational Unit to EFI – Efilers.","required":true,"note":""},{"text":"Select the filer role on the customer record.","required":true,"note":""},{"text":"If address or telephone information is missing, open the pending registration in RAC.","required":false,"note":""},{"text":"Double-click the pending registration row to retrieve available address or telephone information.","required":false,"note":""},{"text":"Add the physical address to the Ivanti customer record.","required":false,"note":""},{"text":"Use Copy to Mail only when the mailing address should match the physical address.","required":false,"note":""},{"text":"Save the completed customer record.","required":true,"note":""}]},{"name":"Review and decide the RAC registration","items":[{"text":"Open RAC → Menu → Security → Registration Applications.","required":true,"note":""},{"text":"Select the correct applicant row.","required":true,"note":""},{"text":"Verify the current approval criteria before making a decision.","required":true,"note":"The source does not fully define the approval criteria."},{"text":"Verify Florida Bar or Pro Hac Vice information when applicable.","required":false,"note":""},{"text":"Approve with the green check when all current criteria are satisfied.","required":false,"note":""},{"text":"Reject with the red X when the application does not meet current criteria.","required":false,"note":""},{"text":"Enter a clear rejection reason and save the RAC decision.","required":false,"note":""}]},{"name":"Communicate and close","items":[{"text":"For a rejection, email the filer from Ivanti with the rejection reason and required correction.","required":false,"note":""},{"text":"For an approval, notify the filer that registration was approved and may require completion from the system email.","required":false,"note":""},{"text":"Tell an approved filer to monitor the appropriate inbox and junk or spam folder.","required":false,"note":""},{"text":"If the completion email is not received, follow the current activation-email support procedure.","required":false,"note":""},{"text":"Change the Ivanti status to Resolved.","required":true,"note":""},{"text":"Add complete resolution notes describing verification, action, communication, and outcome.","required":true,"note":""},{"text":"Select the current Cause Code.","required":true,"note":"The supplied material does not specify the exact Cause Code."},{"text":"Save the resolved ticket.","required":true,"note":""}]}],"customer":["Your registration request has been reviewed.","Monitor the appropriate email inbox and junk or spam folder for any message required to complete registration.","If the registration was rejected, correct the identified information and follow the current registration procedure."],"warning":"Exact approval criteria, standardized rejection reasons, and Cause Codes are not fully defined in the supplied registration procedure."},"access":{"label":"Account Access / Password","purpose":"Verify the Portal account, distinguish the access problem, and document the approved reset, activation, or escalation path.","systems":["Ivanti","RAC","Florida Bar website when applicable","SQL when the current locked-account procedure requires it"],"required":["incidentNumber","customerName","usernameValue","emailValue","statusValue","issueSummary"],"optional":["filerRole","barNumber","phoneValue","dateTime"],"groups":[{"name":"Collect and verify the requester","items":[{"text":"Review the full incident, prior correspondence, and attachments.","required":true,"note":""},{"text":"Confirm the requester is the account holder or is otherwise authorized to receive account information.","required":true,"note":""},{"text":"Collect the account holder’s name, username, associated email, filer role, and exact message.","required":true,"note":""},{"text":"Collect the Florida Bar or Pro Hac Vice number when applicable.","required":false,"note":""},{"text":"Do not request, enter, copy, or record the customer’s password.","required":true,"note":""}]},{"name":"Review the account","items":[{"text":"Locate the account in RAC.","required":true,"note":""},{"text":"Verify the username and email associated with the account.","required":true,"note":""},{"text":"Determine whether the account is pending, inactive, locked, active, duplicated, or associated with another organization.","required":true,"note":""},{"text":"For attorneys, compare relevant information with the Florida Bar website when the current procedure requires it.","required":false,"note":""},{"text":"Check for duplicate or consolidated account concerns before changing the account.","required":false,"note":""},{"text":"For a locked account, complete the current required sysadmin-note or SQL review before reactivation.","required":false,"note":"Confirm the current workaround."}]},{"name":"Apply the correct access procedure","items":[{"text":"Distinguish password reset from registration activation or pending-registration completion.","required":true,"note":""},{"text":"Provide the current Forgot Password procedure when appropriate.","required":false,"note":""},{"text":"Confirm usernames and passwords are case-sensitive.","required":false,"note":""},{"text":"Have the filer remove any displayed password before selecting Forgot Password.","required":false,"note":""},{"text":"Have the filer complete the temporary-password procedure from the associated email.","required":false,"note":""},{"text":"Have the filer select Update after changing account information.","required":false,"note":""},{"text":"Have the filer use the Sign Out hyperlink after updating or leaving the Portal.","required":false,"note":""},{"text":"If the account cannot be safely reactivated or corrected at Tier I, create the appropriate Analyst task.","required":false,"note":""}]},{"name":"Document and close","items":[{"text":"Record the status found in RAC and the email verified for the account.","required":true,"note":""},{"text":"Record the exact reset, activation, reactivation, or escalation action taken.","required":true,"note":""},{"text":"Record the customer communication.","required":true,"note":""},{"text":"Select the current Cause Code and resolve or route the incident appropriately.","required":true,"note":""}]}],"customer":["Enter the current username, remove anything displayed in the password field, and select Forgot Password.","Follow the temporary-password instructions sent to the email associated with the account.","Usernames and passwords are case-sensitive.","After updating the account, select Update and use the Sign Out hyperlink."],"warning":"Temporary-password, activation, and locked-account instructions are security-sensitive and require current-procedure confirmation."},"filing":{"label":"Filing Status / Docket","purpose":"Separate Portal submission status from the Clerk-controlled docket and identify the correct next action.","systems":["Ivanti","RAC","CCIS","MyFLCourtAccess.com / My Submissions"],"required":["incidentNumber","filingNumber","countyValue","issueSummary","statusValue"],"optional":["caseNumber","dateTime","customerName","docketFinding"],"groups":[{"name":"Collect the filing facts","items":[{"text":"Review the complete ticket, attachments, and prior correspondence.","required":true,"note":""},{"text":"Collect the nine-digit filing number rather than only a Workbench submission number.","required":true,"note":""},{"text":"Collect the county, case number when available, submission date/time, and exact customer concern.","required":true,"note":""},{"text":"Determine whether the customer is asking about Portal status, Clerk acceptance, docket placement, or document access.","required":true,"note":""}]},{"name":"Review Portal activity","items":[{"text":"Locate the filing in RAC.","required":true,"note":""},{"text":"Record the current Portal status exactly.","required":true,"note":""},{"text":"Review My Submissions or equivalent submission history when needed.","required":false,"note":""},{"text":"Confirm whether the filing received a filing number.","required":true,"note":""},{"text":"If the item exists only in Workbench, explain that Workbench history does not prove submission.","required":false,"note":""},{"text":"If no filing appears in My Submissions, determine whether the filing must be started again.","required":false,"note":""},{"text":"Check Alerts or Correction Queue when the filing was returned.","required":false,"note":""}]},{"name":"Review Clerk and docket information","items":[{"text":"Review the docket and case parties in CCIS when the issue concerns official filing placement or party status.","required":true,"note":""},{"text":"Record whether the document appears on the official docket.","required":true,"note":""},{"text":"Determine whether the filing is pending, transmitted, validating, sent to local, accepted, rejected, or returned.","required":true,"note":""},{"text":"Determine whether the Clerk has processed the filing.","required":true,"note":""},{"text":"Check whether confidentiality, sealing, closure, disposition, probate status, attorney-of-record status, or document size affects access.","required":false,"note":""},{"text":"Do not represent Portal transmission as Clerk acceptance or docket placement.","required":true,"note":""}]},{"name":"Respond, escalate, and close","items":[{"text":"Explain that the Portal transmits the filing and the Clerk controls the official docket.","required":true,"note":""},{"text":"Refer docket corrections, accepted-filing removal, and case-processing questions to the applicable Clerk.","required":false,"note":""},{"text":"Escalate filings stuck in technical processing statuses using the current Analyst procedure.","required":false,"note":""},{"text":"Record RAC and CCIS findings separately in the ticket.","required":true,"note":""},{"text":"Record the customer’s next action, Clerk referral, or escalation.","required":true,"note":""},{"text":"Resolve or route the incident with the current Cause Code.","required":true,"note":""}]}],"customer":["Open My Submissions to review the current filing status.","The Portal transmits submitted documents to the Clerk.","The Clerk processes filings and controls placement on the official docket."],"warning":"Portal status, Clerk acceptance, and official docket status are separate facts and must not be combined."},"cases":{"label":"My Cases / eService","purpose":"Identify whether the issue concerns case lookup, docket access, case subscription, eService delivery, or the service list.","systems":["Ivanti","MyFLCourtAccess.com","RAC","CCIS when needed"],"required":["incidentNumber","usernameValue","countyValue","caseNumber","issueSummary"],"optional":["filerRole","emailValue","statusValue","docketFinding"],"groups":[{"name":"Identify the exact function","items":[{"text":"Determine whether the customer cannot locate the case, access docket documents, receive case-subscription notices, receive eService, or edit the service list.","required":true,"note":""},{"text":"Collect the Portal username, filer role, county, case number, and email involved.","required":true,"note":""},{"text":"Determine whether the customer is logged into the correct attorney or filer account.","required":true,"note":""}]},{"name":"Troubleshoot My Cases search","items":[{"text":"Search My Cases using a case-party last name.","required":false,"note":""},{"text":"Try the other case party or business name when the first search does not populate the case.","required":false,"note":""},{"text":"Leave Court blank when searching by last name.","required":false,"note":""},{"text":"Remove the last name and search by county when needed.","required":false,"note":""},{"text":"Set Include to All or Active as appropriate.","required":false,"note":""},{"text":"Increase Cases per page when the source procedure requires it.","required":false,"note":""},{"text":"Use the alternate case-lookup method or file to the existing case when required for access.","required":false,"note":""}]},{"name":"Verify docket-access conditions","items":[{"text":"Confirm the attorney is listed as Attorney of Record on the docket when required.","required":false,"note":""},{"text":"Confirm the attorney filed to the case through the attorney Portal account.","required":false,"note":""},{"text":"Check whether the case is disposed, closed, sealed, confidential, or Formal Probate.","required":false,"note":""},{"text":"Check whether the requested document is too large to open through the Portal.","required":false,"note":""},{"text":"Check for a lock or stop-sign symbol indicating confidential or sensitive access restrictions.","required":false,"note":""},{"text":"Refer unavailable docket documents to the Clerk’s website or Clerk request process.","required":false,"note":""}]},{"name":"Troubleshoot eService and notifications","items":[{"text":"Compare the email on the service list with the email in the Portal profile.","required":false,"note":""},{"text":"Check Spam and Junk folders.","required":false,"note":""},{"text":"Confirm the sender is allowed and the organization’s email system is not blocking Portal mail.","required":false,"note":""},{"text":"Confirm the correct persons were selected from the service list.","required":false,"note":""},{"text":"For bounce-back alerts, follow the current clear-alert and reset-counter procedure.","required":false,"note":""},{"text":"Explain that changing the Portal profile does not automatically update existing service lists or Clerk records.","required":true,"note":""},{"text":"Distinguish Portal eService from formal service of a summons.","required":true,"note":""}]},{"name":"Document and close","items":[{"text":"Record the account, case, docket, service-list, and email findings that were actually checked.","required":true,"note":""},{"text":"Record the instructions, Clerk referral, or escalation given to the customer.","required":true,"note":""},{"text":"Resolve or route the incident with the current Cause Code.","required":true,"note":""}]}],"customer":["Confirm whether the concern is locating the case, accessing docket documents, receiving eService, or receiving case-subscription notices.","Profile changes do not automatically update existing eService lists or Clerk records.","Portal eService is not the same as formal service of a summons."],"warning":"Dated email allowlisting, bounce-back, and eService protocol language must be verified before use."},"upload":{"label":"Upload / PDF / Browser","purpose":"Collect technical evidence, validate the browser and document, perform a clean-slate retry, and escalate only after documenting the result.","systems":["Ivanti","MyFLCourtAccess.com","Customer browser/device","Customer file","Analyst / Tier II when unresolved"],"required":["incidentNumber","exactError","browserValue","deviceValue","documentName","fileTypeValue","issueSummary"],"optional":["filingNumber","usernameValue","fileSizeValue","pageSizeValue","filenameValue","securityValue","dateTime","impactValue","troubleshootingValue","attachmentsValue","reproValue"],"groups":[{"name":"Collect technical evidence","items":[{"text":"Record the exact error text or exact point where the filing stops.","required":true,"note":""},{"text":"Record the date/time, Portal username or user number, filing number, county, and case number when available.","required":false,"note":""},{"text":"Record the browser, browser version, device, and operating environment.","required":true,"note":""},{"text":"Determine whether one computer, the entire office, or outside users are affected.","required":false,"note":""},{"text":"Collect screenshots when the error or page state can be shown.","required":false,"note":""},{"text":"Record the customer’s internet provider and last browser update when investigating slowness or timeouts.","required":false,"note":""}]},{"name":"Reset the Portal session and browser","items":[{"text":"Confirm the filer is not using an unsupported phone, tablet, browser, or device.","required":true,"note":""},{"text":"Have the filer use the Sign Out hyperlink and sign back in.","required":true,"note":""},{"text":"Confirm the filer uses Sign Out when leaving the website and after extended inactivity.","required":false,"note":""},{"text":"Have the filer hand-key MyFLCourtAccess.com instead of using a saved link.","required":false,"note":""},{"text":"Clear browser cache and cookies.","required":true,"note":""},{"text":"Update the browser.","required":true,"note":""},{"text":"Allow pop-ups and redirects for the Portal.","required":true,"note":""},{"text":"Try a different supported browser.","required":false,"note":""},{"text":"Try a different computer.","required":false,"note":""},{"text":"Restart the computer.","required":false,"note":""},{"text":"For payment or page-function issues, try a private/incognito browser session when appropriate.","required":false,"note":""}]},{"name":"Validate the filing and document","items":[{"text":"Start the filing again from the beginning.","required":true,"note":""},{"text":"Do not resume the failed filing from Workbench.","required":true,"note":""},{"text":"Confirm the total filing size is within the current Portal limit.","required":false,"note":""},{"text":"Upload one document at a time and allow each upload to finish.","required":true,"note":""},{"text":"Confirm the file is PDF or PDF/A.","required":true,"note":""},{"text":"For scanned pages, confirm the current DPI requirement.","required":false,"note":""},{"text":"Confirm the file is not compressed or zipped.","required":true,"note":""},{"text":"Confirm the PDF is not locked, secured, or password-protected.","required":true,"note":""},{"text":"Review the filename for special or odd characters.","required":true,"note":""},{"text":"Confirm the filename is within the current character limit.","required":true,"note":"The sources contain conflicting 32- and 36-character statements."},{"text":"Confirm the page size does not exceed 8.5 × 11 inches.","required":true,"note":""},{"text":"Review current restrictions concerning color documents, signatures, pictures, and videos.","required":false,"note":""},{"text":"If the file is XFA, convert it to an acceptable standard PDF using the current procedure.","required":false,"note":""},{"text":"If the PDF is corrupt, missing, stacked, or visually altered, recreate or re-export it before retrying.","required":false,"note":""}]},{"name":"Check issue-specific symptoms","items":[{"text":"For an upload stuck at 100%, wait until the progress indicator fully changes or disappears before adding another document.","required":false,"note":""},{"text":"For Document #2 incomplete, treat stale session or incomplete upload as possible causes and restart the filing.","required":false,"note":""},{"text":"For a missing or disabled Submit button, verify required filing fields, confidentiality selections, documents, parties, and payment steps.","required":false,"note":""},{"text":"For preview failures, review the browser or Adobe extension setting identified in the source.","required":false,"note":""},{"text":"For Origin Key errors, change browsers and capture F12 Console information if escalation is required.","required":false,"note":""},{"text":"For timeout or webpage-load issues, check pop-up blocking, redirects, browser updates, restart status, internet speed, and IT/network involvement.","required":false,"note":""},{"text":"When applicable, have the customer’s IT department review the current firewall/domain allowlist.","required":false,"note":""}]},{"name":"Reproduce, escalate, and close","items":[{"text":"Attempt to reproduce the issue when authorized and safe.","required":false,"note":""},{"text":"Record every troubleshooting step completed and the result of each step.","required":true,"note":""},{"text":"Record whether the issue is reproducible and whether multiple users are affected.","required":false,"note":""},{"text":"Create a complete Analyst / Tier II task when the documented clean-slate attempt fails.","required":false,"note":""},{"text":"Attach screenshots and supporting details to the escalation.","required":false,"note":""},{"text":"Record the customer communication and next step in Ivanti.","required":true,"note":""},{"text":"Resolve only when the issue is fixed, referred, or properly escalated.","required":true,"note":""}]}],"customer":["Use the Sign Out hyperlink, sign back in, and begin a new filing instead of resuming the failed Workbench item.","Clear browser cache and cookies, update the browser, and allow pop-ups and redirects.","Confirm the document meets the current PDF, size, filename, page-size, security, and upload-completion requirements."],"warning":"The sources contain conflicting filename limits and potentially changeable browser, firewall, color, and document requirements."},"payment":{"label":"Payment / Charge / Refund","purpose":"Identify the transaction, troubleshoot the payment method, determine ownership, and document the correct Portal, banking, or Clerk path.","systems":["Ivanti","TPE","RAC / My Submissions","Banking team when appropriate","Clerk when appropriate"],"required":["incidentNumber","paymentTypeValue","lastFourValue","amountValue","chargeDateValue","customerName","issueSummary"],"optional":["filingNumber","descriptorValue","browserValue","usernameValue","statusValue","docketFinding"],"groups":[{"name":"Collect transaction details","items":[{"text":"Collect the payment type: credit, debit, or ACH.","required":true,"note":""},{"text":"Collect only the last four digits of the payment account or card.","required":true,"note":""},{"text":"Collect the exact charge date and amount.","required":true,"note":""},{"text":"Collect the account holder name, filing number, and statement descriptor or reference when available.","required":true,"note":""},{"text":"Do not collect or record a full card or bank-account number.","required":true,"note":""}]},{"name":"Research the charge and filing","items":[{"text":"Research the charge in TPE using the available date, amount, and account information.","required":true,"note":""},{"text":"Review the related filing in RAC or My Submissions.","required":true,"note":""},{"text":"Determine whether the charge is associated with a completed filing, pending filing, correction, saved payment, or unknown transaction.","required":true,"note":""},{"text":"Determine whether the Clerk accepted the filing and pulled the funds.","required":false,"note":""},{"text":"Determine whether the requested refund belongs to the Portal/banking process or the Clerk.","required":true,"note":""}]},{"name":"Troubleshoot payment processing","items":[{"text":"Determine whether the customer is using a saved payment method.","required":false,"note":""},{"text":"Have the customer hand-key the payment information instead of using the saved method.","required":false,"note":""},{"text":"Confirm whether the customer selected Save payment for Future Use.","required":false,"note":""},{"text":"Ask when the exact payment method last worked successfully.","required":false,"note":""},{"text":"Ask whether the card is new or the bank name or expiration date changed.","required":false,"note":""},{"text":"Ask whether the Portal username or password recently changed.","required":false,"note":""},{"text":"Confirm the supported browser and try a different browser when appropriate.","required":false,"note":""},{"text":"Try a private/incognito browser session when appropriate.","required":false,"note":""},{"text":"Clear cache and cookies, update the browser, allow pop-ups, and restart the computer.","required":false,"note":""},{"text":"Check whether a prior payment is still processing or tied to a Correction Queue item.","required":false,"note":""},{"text":"Have the customer’s IT department review current firewall/domain requirements when needed.","required":false,"note":""}]},{"name":"Refund, receipt, and ownership path","items":[{"text":"For a Portal overpayment, collect the filing number and send complete information to the current banking/refund process.","required":false,"note":""},{"text":"For funds pulled by the Clerk, direct the customer to the correct Clerk division.","required":false,"note":""},{"text":"Do not promise or issue a refund before ownership and eligibility are verified.","required":true,"note":""},{"text":"For recent receipts, review the current Email Log / Processing Completed or My Fees procedure.","required":false,"note":""},{"text":"Record the transaction ownership and exact next action.","required":true,"note":""}]},{"name":"Document and close","items":[{"text":"Record the TPE and filing findings.","required":true,"note":""},{"text":"Record the troubleshooting performed.","required":false,"note":""},{"text":"Record the Portal, banking, or Clerk referral provided.","required":true,"note":""},{"text":"Resolve or escalate using the current Cause Code.","required":true,"note":""}]}],"customer":["Provide the payment type, last four digits only, charge date, exact amount, account holder, and filing number when available.","Support will determine whether the request follows the Portal, banking, or Clerk process."],"warning":"Never collect full payment credentials, and never promise a refund before the responsible party and eligibility are verified."},"correction":{"label":"Wrong Attorney / County / Correction","purpose":"Verify the filing and docket before selecting Correction Queue, refiling, eService maintenance, or Clerk action.","systems":["Ivanti","RAC","CCIS","MyFLCourtAccess.com","Clerk when required"],"required":["incidentNumber","filingNumber","countyValue","issueSummary","statusValue"],"optional":["caseNumber","correctCountyValue","attorneyUsedValue","correctAttorneyValue","docketFinding","dateTime"],"groups":[{"name":"Collect and identify the correction","items":[{"text":"Collect the filing number, county, case number, filer account, and exact correction requested.","required":true,"note":""},{"text":"Determine whether the issue is wrong attorney, wrong county, wrong case, case-party information, document content, or returned filing.","required":true,"note":""},{"text":"Collect the correct attorney, county, case, or party information when known.","required":false,"note":""}]},{"name":"Verify filing and docket status","items":[{"text":"Locate the filing in RAC and record the exact status.","required":true,"note":""},{"text":"Review the official docket in CCIS.","required":true,"note":""},{"text":"Determine whether the filing is still editable, in Correction Queue, transmitted, accepted, rejected, or docketed.","required":true,"note":""},{"text":"Determine whether the Clerk has already processed the filing.","required":true,"note":""},{"text":"Do not instruct the customer to use the Portal to alter or remove an official docket entry.","required":true,"note":""}]},{"name":"Select the applicable correction path","items":[{"text":"For a returned filing, follow the current Correction Queue procedure.","required":false,"note":""},{"text":"For Correction Queue payment failure, complete applicable payment troubleshooting before escalation.","required":false,"note":""},{"text":"For a filing under the wrong attorney, verify the attorney account and current refiling or Clerk procedure.","required":false,"note":""},{"text":"For a filing under the wrong county, verify the filed county and correct county before giving refiling instructions.","required":false,"note":""},{"text":"For case-number, division, or county changes, verify the correct case information and Clerk ownership.","required":false,"note":""},{"text":"For missing or incorrect case parties, review case-party and Filed On Behalf Of procedures.","required":false,"note":""},{"text":"For a document that changed while being corrected, verify the uploaded file and recreate the filing when necessary.","required":false,"note":""},{"text":"For accepted or docketed filings, refer correction or removal requests to the applicable Clerk.","required":false,"note":""},{"text":"Review whether eService or service-list maintenance is needed after a corrected filing.","required":false,"note":""}]},{"name":"Communicate and close","items":[{"text":"Explain the difference between a Portal correction and a Clerk-controlled docket correction.","required":true,"note":""},{"text":"Provide the verified Correction Queue, refiling, or Clerk next step.","required":true,"note":""},{"text":"Record RAC and CCIS findings.","required":true,"note":""},{"text":"Record the customer communication and outcome.","required":true,"note":""},{"text":"Resolve or escalate with the current Cause Code.","required":true,"note":""}]}],"customer":["Portal Support can assist with technical Portal correction or refiling steps.","Corrections to an accepted or docketed filing may require action by the applicable Clerk."],"warning":"The path depends on whether the filing is still in Portal processing, returned for correction, accepted, or already on the official docket."},"technical":{"label":"Known Issue / Technical Error","purpose":"Collect enough evidence to reproduce, correlate, and escalate the problem without forcing Analyst / Tier II to repeat Tier I work.","systems":["Ivanti","RAC","CCIS","TPE","SQL when applicable","Portal","Analyst / Tier II"],"required":["incidentNumber","exactError","dateTime","browserValue","issueSummary","troubleshootingValue","impactValue"],"optional":["usernameValue","filingNumber","countyValue","caseNumber","attachmentsValue","reproValue","docketFinding","deviceValue"],"groups":[{"name":"Collect the incident evidence","items":[{"text":"Record the exact error, exact page, and exact action that triggered it.","required":true,"note":""},{"text":"Record the date/time, username or user number, filer role, organization, filing number, county, and case number when available.","required":true,"note":""},{"text":"Record the browser, version, device, and operating environment.","required":true,"note":""},{"text":"Determine whether one user, multiple users, one office, or users outside the office are affected.","required":true,"note":""},{"text":"Record the business impact and any filing deadline.","required":true,"note":""},{"text":"Collect screenshots, error text, and reproducible steps.","required":true,"note":""},{"text":"For slowness, record dates, internet provider, and last browser update.","required":false,"note":""}]},{"name":"Complete Tier I investigation","items":[{"text":"Review the relevant account or filing in RAC.","required":false,"note":""},{"text":"Review the docket or case parties in CCIS when relevant.","required":false,"note":""},{"text":"Review TPE when the error concerns payment.","required":false,"note":""},{"text":"Run the current approved SQL script when the procedure requires it.","required":false,"note":""},{"text":"Complete the applicable browser, session, file, payment, or Portal troubleshooting.","required":true,"note":""},{"text":"Attempt reproduction when authorized.","required":false,"note":""},{"text":"Record whether the error reproduces and under what conditions.","required":true,"note":""},{"text":"For Origin Key errors, capture the browser Console sequence when required.","required":false,"note":""}]},{"name":"Check scope and duplication","items":[{"text":"Search for an existing known issue or Master Ticket.","required":true,"note":""},{"text":"Determine whether the incident should be attached to a Master Ticket.","required":false,"note":""},{"text":"Check for duplicate tickets from the same customer or issue.","required":false,"note":""},{"text":"Use one primary ticket and document related ticket numbers when multiple tickets exist.","required":false,"note":""},{"text":"Transcribe or consolidate relevant ticket information using the current internal process.","required":false,"note":""}]},{"name":"Build the escalation","items":[{"text":"State the problem in one clear sentence.","required":true,"note":""},{"text":"Include all identifiers and system findings.","required":true,"note":""},{"text":"List every troubleshooting step already completed and its result.","required":true,"note":""},{"text":"Include reproduction results, user scope, and business impact.","required":true,"note":""},{"text":"Attach screenshots and supporting files.","required":true,"note":""},{"text":"State the specific Analyst / Tier II action requested.","required":true,"note":""},{"text":"Keep the customer informed using the current escalation language.","required":true,"note":""}]},{"name":"Follow through and close","items":[{"text":"Keep the primary Ivanti incident open while Analyst work is pending unless current procedure says otherwise.","required":false,"note":""},{"text":"Document Analyst updates and customer contacts.","required":false,"note":""},{"text":"Confirm the issue is resolved or a final supported next step was provided.","required":true,"note":""},{"text":"Close related or duplicate incidents according to the current Master Ticket process.","required":false,"note":""},{"text":"Select the current Cause Code and save the final ticket.","required":true,"note":""}]}],"customer":["Provide the exact error text, date and time, browser and version, relevant Portal identifiers, screenshots, and the steps immediately preceding the error.","Support will document the investigation and route it for additional technical review when required."],"warning":"A useful escalation includes identifiers, system findings, completed troubleshooting, reproduction results, scope, impact, evidence, and the requested Analyst action."},"clerk":{"label":"Clerk Referral / Procedural Question","purpose":"Verify enough Portal information to determine that the requested action belongs to the Clerk or another court-related office.","systems":["Ivanti","RAC or My Submissions when needed","CCIS when needed"],"required":["incidentNumber","countyValue","issueSummary"],"optional":["caseNumber","filingNumber","statusValue","docketFinding","customerName"],"groups":[{"name":"Identify the request","items":[{"text":"Read the complete ticket and identify the exact question or action requested.","required":true,"note":""},{"text":"Collect the county, case number, filing number, and case type when available.","required":true,"note":""},{"text":"Determine whether the customer is asking for legal advice, form selection, court procedure, case status, docket action, summons procedure, copies, court appearance information, or another case-specific decision.","required":true,"note":""}]},{"name":"Verify Portal ownership","items":[{"text":"Review Portal status when the question may still involve an unsubmitted or technically failed filing.","required":false,"note":""},{"text":"Review RAC or My Submissions when needed to establish whether Portal processing is complete.","required":false,"note":""},{"text":"Review CCIS when needed to establish that the issue concerns the official docket or case parties.","required":false,"note":""},{"text":"Do not answer a legal or procedural question merely because the customer included Portal details.","required":true,"note":""}]},{"name":"Apply the support boundary","items":[{"text":"Explain that Portal Support provides navigation and technical assistance for MyFLCourtAccess.com.","required":true,"note":""},{"text":"Do not select forms or tell the customer what they are legally required to file.","required":true,"note":""},{"text":"Do not interpret court rules, deadlines, summons requirements, or confidential-case requirements.","required":true,"note":""},{"text":"Do not change, rescind, remove, or correct the official docket.","required":true,"note":""},{"text":"Do not forward customer documents or email content to the Clerk or Judge as a filing.","required":true,"note":""},{"text":"Direct the customer to the Clerk in the county where the case is or will be filed.","required":true,"note":""},{"text":"For summons questions, distinguish Portal eService from formal service and refer procedure questions to the Clerk or service agency.","required":false,"note":""},{"text":"For Clerk-controlled refunds, certified copies, court appearance, ADA, or sealed/confidential matters, direct the customer to the applicable office.","required":false,"note":""}]},{"name":"Document and close","items":[{"text":"Record the Portal facts checked before the referral.","required":true,"note":""},{"text":"Record why the issue is Clerk-controlled or outside Portal Support scope.","required":true,"note":""},{"text":"Record the Clerk or office referral given to the customer.","required":true,"note":""},{"text":"Resolve the incident with the current Cause Code.","required":true,"note":""}]}],"customer":["Portal Support provides navigational and technical assistance for MyFLCourtAccess.com.","Portal Support cannot provide legal advice, select forms, explain court procedure, change the docket, or determine case status.","Contact the Clerk in the county where the case is or will be filed for case-specific assistance."],"warning":"Portal Support should verify enough information to establish ownership, but should not cross into legal advice or Clerk-controlled case procedure."}},"fields":{"incidentNumber":["Incident number","text","Ticket or incident number"],"customerName":["Customer name","text","Only what is needed for the ticket"],"emailValue":["Email address","email","Associated or contact email"],"phoneValue":["Telephone","text","Contact number"],"addressValue":["Physical / mailing address","text","When required"],"filerRole":["Filer role","text","Attorney, PHV, SRL, organization..."],"barNumber":["Florida Bar / PHV number","text","When applicable"],"usernameValue":["Username / user number","text","Never enter a password"],"filingNumber":["Filing number","text","Nine-digit filing number when applicable"],"caseNumber":["Case number","text","When applicable"],"countyValue":["County / court","text","County where filed or filing"],"dateTime":["Date and time","datetime-local",""],"issueSummary":["Customer issue","textarea","Describe the issue or request"],"exactError":["Exact error text","textarea","Copy the error exactly"],"statusValue":["Current status / account message","text","RAC status, filing status, inactive/locked message..."],"docketFinding":["RAC / CCIS / TPE / SQL findings","textarea","Record what each system showed"],"browserValue":["Browser and version","text","Edge, Chrome, Firefox..."],"deviceValue":["Device","text","Computer, Mac, phone, tablet..."],"documentName":["Document name / type","text",""],"fileTypeValue":["File type","text","PDF, PDF/A..."],"fileSizeValue":["Combined file size","text",""],"pageSizeValue":["Page size","text","Example: 8.5 × 11"],"filenameValue":["Filename","text",""],"securityValue":["Locked / secured status","text","Unlocked, secured, password-protected..."],"impactValue":["Business impact","text","Single user, multiple users, deadline..."],"troubleshootingValue":["Troubleshooting already completed","textarea","List exact steps already attempted"],"attachmentsValue":["Screenshots / attachments","textarea","Describe evidence without unnecessary sensitive data"],"reproValue":["Reproducible?","select",["","Yes","No","Not tested"]],"paymentTypeValue":["Payment type","text","Card, ACH..."],"lastFourValue":["Last four digits only","text","Never enter a full account number"],"amountValue":["Exact amount","text","$0.00"],"chargeDateValue":["Charge date","date",""],"descriptorValue":["Statement descriptor / reference","text",""],"correctCountyValue":["Correct county","text",""],"attorneyUsedValue":["Attorney used","text",""],"correctAttorneyValue":["Correct attorney","text",""]},"troubleshootingCards":[{"id":"complete-clean-slate","title":"Complete Clean-Slate Troubleshooting Reply","category":"Complete Replies","verify":true,"note":"Full first-line troubleshooting sequence.","text":"Hello, and thank you for contacting the E-Filing Portal website MyFLCourtAccess.com Help Desk.\n\nWhen an issue like this is reported, please see the below to assist in troubleshooting.\n\nDo not use the Safari web browser if you are using an Apple/MAC computer.\n\nDo not try to file from a phone or tablet.\n\nYou can also use the following steps below to reset information to file from a \"clean slate\".\n\nAs insignificant as the Sign Out instructions may seem, if you do not use them, you may experience issues with:\nInformation in your corrections filing disappearing.\nUploading: will upload a different PDF file than what you chose\nInability to make payments\nInability to submit the filing\nMay check the box for emergency filing\nSlowness on the website\n\nSign Out using the Sign Out hyperlink, and sign back in.\n\nSigning Out should be done:\n\na. Every time you leave the website.\n\nb. After 15-20 minutes of being idle.\n\nIf not, it can cause issues with functions on the website.\n\nHave you checked the formatting of your electronic file: No color, has to be unlocked/unsecured, no zipped / compressed files.\n\nInstead of using a saved link, hand key the website into the URL address bar on the web browser.\n\n1. Clear your web browser cache / cookies and update the browser at least every 2 weeks.\n\n2. Make sure in your web browser settings, you list our website the allowance for pop ups and redirects.\n\n3. Verify with your IT Department that the following websites are allowed access through your firewall as 1 or 2 of the sites needed are coming out of the Netherlands:\nhttps://checkoutshopper-live.adyen.com and *.myflcourtaccess.com, *.vimeocdn.com, *.vimeo.com, *.jsdelivr.net, and *.typekit.net.\n\nIf you are trying to file to a case:  Start your filing over from the beginning.\n\nDo NOT pull and resume any submission from the workbench.\n\nIf the above does not work, try a different web browser or from a different computer to see if your results are any different.\n\nRestart your machine after the troubleshooting steps have been used.\n\nI cannot guarantee this will fix the issue, but they are the steps that we ask you to apply first."},{"id":"unsupported-safari","title":"Safari on Apple/Mac","category":"Device and Browser","verify":true,"note":"Confirm current browser support.","text":"Do not use the Safari web browser if you are using an Apple/MAC computer."},{"id":"phone-tablet","title":"Phone or Tablet Filing","category":"Device and Browser","verify":true,"note":"Confirm current device support.","text":"Do not try to file from a phone or tablet."},{"id":"stale-session","title":"Symptoms of Improper Sign-Out","category":"Session and Workbench","verify":true,"note":"","text":"As insignificant as the Sign Out instructions may seem, if you do not use them, you may experience issues with:\nInformation in your corrections filing disappearing.\nUploading: will upload a different PDF file than what you chose\nInability to make payments\nInability to submit the filing\nMay check the box for emergency filing\nSlowness on the website"},{"id":"sign-out","title":"Sign Out and Sign Back In","category":"Session and Workbench","verify":true,"note":"","text":"Sign Out using the Sign Out hyperlink, and sign back in.\n\nSigning Out should be done:\n\na. Every time you leave the website.\n\nb. After 15-20 minutes of being idle.\n\nIf not, it can cause issues with functions on the website."},{"id":"basic-file","title":"Basic Electronic-File Check","category":"Documents and Uploading","verify":true,"note":"","text":"Have you checked the formatting of your electronic file: No color, has to be unlocked/unsecured, no zipped / compressed files."},{"id":"hand-key","title":"Hand-Key the Portal Address","category":"Device and Browser","verify":false,"note":"","text":"Instead of using a saved link, hand key the website into the URL address bar on the web browser."},{"id":"cache","title":"Clear Cache, Cookies, and Update Browser","category":"Device and Browser","verify":true,"note":"The two-week interval is source wording and may change.","text":"1. Clear your web browser cache / cookies and update the browser at least every 2 weeks."},{"id":"popups","title":"Allow Pop-Ups and Redirects","category":"Device and Browser","verify":false,"note":"","text":"2. Make sure in your web browser settings, you list our website the allowance for pop ups and redirects."},{"id":"firewall","title":"Firewall and Domain Allowlist","category":"Network and Firewall","verify":true,"note":"Infrastructure domains may change.","text":"3. Verify with your IT Department that the following websites are allowed access through your firewall as 1 or 2 of the sites needed are coming out of the Netherlands:\nhttps://checkoutshopper-live.adyen.com and *.myflcourtaccess.com, *.vimeocdn.com, *.vimeo.com, *.jsdelivr.net, and *.typekit.net."},{"id":"restart-filing","title":"Start the Filing Over","category":"Session and Workbench","verify":false,"note":"","text":"If you are trying to file to a case:  Start your filing over from the beginning."},{"id":"no-workbench","title":"Do Not Resume From Workbench","category":"Session and Workbench","verify":true,"note":"","text":"Do NOT pull and resume any submission from the workbench."},{"id":"different-browser","title":"Try Another Browser or Computer","category":"Device and Browser","verify":false,"note":"","text":"If the above does not work, try a different web browser or from a different computer to see if your results are any different."},{"id":"restart-machine","title":"Restart the Computer","category":"Device and Browser","verify":false,"note":"","text":"Restart your machine after the troubleshooting steps have been used.\n\nI cannot guarantee this will fix the issue, but they are the steps that we ask you to apply first."},{"id":"complete-upload","title":"Complete Upload and Filing-Environment Reply","category":"Complete Replies","verify":true,"note":"","text":"We also provide the following steps to provide you with a better filing environment.\nI am going to list the below information, highlighting on some points I feel are important.\nI know you may have tried of the items on here, but because I have only had 2 people report something similar to this issue, and it's not widespread,\nI am limited on what assistance I can offer.\n\nOn uploading, the formatting and the names of the files are crucial:\n\nPlease adhere to the information below when filing.\n\nYou cannot use the Safari web browser that is on most Apple/Mac devices.\n\nYour file must be in PDF or PDF/a format.\n\nIf you are scanning pages into a PDF, make sure they are at 300DPI\n\n*Will NOT accept compressed or zipped files.\n\n*Will NOT accept PDF files if the file name has special or odd characters\n\nIn naming your PDF file:\n\nDo NOT use hyphens, underscores, or odd characters (%^&*( )=+) or web dings\n\n*Will NOT accept PDF files if the file name exceeds 36 characters in length.\n\n*Will not accept “locked” or “Secured” PDF files.\n\n***NO VIDEOS*** Please call the clerk of the court in the county your case is filed in and ask how to get that submitted to them\n\n**NO COLOR PICTURES** If they must be in color, call the clerk to ask how to submit them outside of the portal.\n\nNo document in color other than black, including the signatures will be accepted.\n\nThe page size cannot exceed 8.5 x 11\n\nDO NOT SAVE TO THE WORKBENCH TO GO BACK LATER TO RESUME.\n\nIT WILL NOT WORK.\n\nWhen uploading documents: make sure the 100% bar changes to a decimal number. If it does not, you cannot upload other documents."},{"id":"pdf-format","title":"PDF or PDF/A Requirement","category":"Documents and Uploading","verify":true,"note":"","text":"You cannot use the Safari web browser that is on most Apple/Mac devices.\n\nYour file must be in PDF or PDF/a format."},{"id":"scan-dpi","title":"Scanned Pages at 300 DPI","category":"Documents and Uploading","verify":true,"note":"","text":"If you are scanning pages into a PDF, make sure they are at 300DPI"},{"id":"no-zip","title":"No Compressed or ZIP Files","category":"Documents and Uploading","verify":false,"note":"","text":"*Will NOT accept compressed or zipped files."},{"id":"filename-chars","title":"Filename Characters","category":"Documents and Uploading","verify":true,"note":"","text":"*Will NOT accept PDF files if the file name has special or odd characters\n\nIn naming your PDF file:\n\nDo NOT use hyphens, underscores, or odd characters (%^&*( )=+) or web dings"},{"id":"filename-length","title":"Filename Length Limit","category":"Documents and Uploading","verify":true,"note":"Other supplied source material contains a conflicting 32-character statement.","text":"*Will NOT accept PDF files if the file name exceeds 36 characters in length."},{"id":"secured","title":"Locked or Secured PDF","category":"Documents and Uploading","verify":false,"note":"","text":"*Will not accept “locked” or “Secured” PDF files."},{"id":"no-videos","title":"Video Submission","category":"Documents and Uploading","verify":true,"note":"","text":"***NO VIDEOS*** Please call the clerk of the court in the county your case is filed in and ask how to get that submitted to them"},{"id":"color","title":"Color Pictures and Non-Black Content","category":"Documents and Uploading","verify":true,"note":"","text":"**NO COLOR PICTURES** If they must be in color, call the clerk to ask how to submit them outside of the portal.\n\nNo document in color other than black, including the signatures will be accepted."},{"id":"page-size","title":"Page Size Limit","category":"Documents and Uploading","verify":true,"note":"","text":"The page size cannot exceed 8.5 x 11"},{"id":"workbench-warning","title":"Do Not Save and Resume From Workbench","category":"Session and Workbench","verify":true,"note":"","text":"DO NOT SAVE TO THE WORKBENCH TO GO BACK LATER TO RESUME.\n\nIT WILL NOT WORK."},{"id":"upload-progress","title":"Upload Progress Must Change From 100%","category":"Documents and Uploading","verify":true,"note":"","text":"When uploading documents: make sure the 100% bar changes to a decimal number. If it does not, you cannot upload other documents."},{"id":"dmarc","title":"Yahoo, Gmail, AOL, and DMARC/DKIM Reply","category":"Email Delivery","verify":true,"note":"Dated external-provider guidance; verify before use.","text":"Yahoo, Gmail, and AOL users:\nIf you run into a DMARC/DKIM issue, we are unable to correct this for you.\nThe Florida Courts E-Filing Portal has performed due diligence on our end to ensure our compliance to Google, Yahoo, and AOL's new requirements via Microsoft.\nWe have not experienced any issues from this.\n\nIf you have an email address that is hosted by Yahoo, Google, or AOL; please be aware of the following changes that these companies had imposed effective February 1, 2024.\nPlease visit the website below or search on their websites to see what responsibilities you may have and to make sure you are aware of any changes you may need to make.\n\nhttps://www.proofpoint.com/us/blog/email-and-cloud-threats/google-and-yahoo-set-new-email-authentication-requirements"},{"id":"troubleshooting-note","title":"Troubleshooting Steps Emailed","category":"Internal Documentation","verify":false,"note":"","text":"Emailed troubleshooting steps."},{"id":"dmarc-note","title":"DMARC Link Emailed","category":"Internal Documentation","verify":false,"note":"","text":"emailed the Proofpoint/DMARC link for Yahoo and Gmail users information"}],"troubleshootingChecklist":[{"group":"Issue and Identifiers","text":"Record the exact error or symptom and the exact point where the customer becomes stuck."},{"group":"Issue and Identifiers","text":"Record the date and time of the issue."},{"group":"Issue and Identifiers","text":"Collect the Portal username or user number when applicable."},{"group":"Issue and Identifiers","text":"Collect the filing number, county, and case number when available."},{"group":"Issue and Identifiers","text":"Collect screenshots or the exact error text."},{"group":"Scope and Environment","text":"Determine whether one computer, the whole office, or outside users are affected."},{"group":"Scope and Environment","text":"Record the browser and browser version."},{"group":"Scope and Environment","text":"Record the device and operating environment."},{"group":"Scope and Environment","text":"For slowness or timeouts, record the internet provider and last browser update."},{"group":"Session Reset","text":"Have the filer use the Sign Out hyperlink and sign back in."},{"group":"Session Reset","text":"Confirm Sign Out is used when leaving the website and after extended inactivity."},{"group":"Session Reset","text":"Have the filer hand-key MyFLCourtAccess.com instead of using a saved link."},{"group":"Browser Reset","text":"Clear browser cache and cookies."},{"group":"Browser Reset","text":"Update the browser."},{"group":"Browser Reset","text":"Allow pop-ups and redirects for the Portal."},{"group":"Browser Reset","text":"Try a different supported browser."},{"group":"Browser Reset","text":"Try a private/incognito browser session when appropriate."},{"group":"Browser Reset","text":"Try a different computer."},{"group":"Browser Reset","text":"Restart the computer."},{"group":"Network and IT","text":"Have IT review current Portal and payment firewall/domain requirements when applicable."},{"group":"Network and IT","text":"For load or timeout issues, have IT or the internet provider review connectivity and internet speed."},{"group":"Filing Reset","text":"Start the filing over from the beginning."},{"group":"Filing Reset","text":"Do not pull or resume the failed submission from Workbench."},{"group":"Filing Reset","text":"When the current procedure requires it, keep the initiating document first in the upload order."},{"group":"Document Validation","text":"Confirm the total filing size is within the current Portal limit."},{"group":"Document Validation","text":"Upload one document at a time and allow each upload to finish."},{"group":"Document Validation","text":"Confirm the file is PDF or PDF/A."},{"group":"Document Validation","text":"For scanned pages, confirm the current DPI requirement."},{"group":"Document Validation","text":"Confirm the file is not compressed or zipped."},{"group":"Document Validation","text":"Confirm the PDF is not locked, secured, or password-protected."},{"group":"Document Validation","text":"Review the filename for special or odd characters."},{"group":"Document Validation","text":"Confirm the filename is within the current character limit; the supplied sources conflict."},{"group":"Document Validation","text":"Confirm the page size does not exceed 8.5 × 11 inches."},{"group":"Document Validation","text":"Review current restrictions concerning color documents, signatures, pictures, and videos."},{"group":"Document Validation","text":"Convert XFA forms to an acceptable standard PDF when applicable."},{"group":"Document Validation","text":"Recreate or re-export corrupt, missing, stacked, or visually altered PDFs."},{"group":"Issue-Specific Checks","text":"For an upload at 100%, wait for the upload indicator to fully change or disappear before adding another document."},{"group":"Issue-Specific Checks","text":"For Document #2 incomplete, restart the filing after completing the session and upload checks."},{"group":"Issue-Specific Checks","text":"For a disabled Submit button, verify required fields, parties, documents, confidentiality selections, and payment steps."},{"group":"Issue-Specific Checks","text":"For preview failures, review the browser or Adobe extension setting identified in the source."},{"group":"Issue-Specific Checks","text":"For Origin Key errors, change browsers and capture F12 Console information when escalating."},{"group":"Escalation","text":"Attempt reproduction when authorized."},{"group":"Escalation","text":"Record every troubleshooting step and the result."},{"group":"Escalation","text":"Record whether one or multiple users are affected and the business impact."},{"group":"Escalation","text":"Attach screenshots and identifiers to the Analyst / Tier II task."}],"quickReplies":[{"id":"reply-2-3","title":"Standard Greeting and Portal Scope","category":"Openings and Closures","audience":"Customer-facing","verify":false,"warning":"","text":"Hello, and thank you for contacting the E-Filing Portal website MyFLCourtAccess.com Help Desk.\nAs we are not the Clerk of the Courts, we can only answer questions related to navigating the e-filing website MyFLCourtAccess.com to upload documentation."},{"id":"reply-5-6","title":"Do Not Reply / Submit New Help Request","category":"Openings and Closures","audience":"Customer-facing","verify":true,"warning":"Confirm the current contact page and reply-handling procedure.","text":"Please do not reply to this email.If you have any additional inquiries as it pertains to e-filing or if the issue is unresolved, you can send in a request to the help desk by going to the website:\nhttps://www.myflcourtaccess.com/Common/UIPages/Contactus.aspx"},{"id":"reply-8-8","title":"Clerk Referral Logged","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Referring to contact the Clerk &/or visit the clerk website for: access to documents, information on forms &/or procedural guidance."},{"id":"reply-9-9","title":"New-Case Filing Guidance Sent","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Emailed guidance on how to- navigate the website to file documentation for a new case."},{"id":"reply-11-11","title":"Existing-Case Filing Guidance Sent","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Emailed guidance on how to- file documentation to an existing case."},{"id":"reply-12-12","title":"Registration and Existing-Case Guidance Sent","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Emailed guidance on registration & how to- file documentation to an existing case."},{"id":"reply-13-13","title":"Oversized-Document Instructions Sent","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Emailed instructions for resizing oversized documents."},{"id":"reply-15-16","title":"Do Not Use DIY Module","category":"Filing Guidance","audience":"Customer-facing","verify":true,"warning":"The source says there may be an issue with DIY; confirm current status.","text":"Please do not use the DIY module for your filing. There may be an issue with it at this time.\nPlease use the guidance for the standard method outlined below."},{"id":"reply-18-18","title":"Username and Password Reset Sent","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Emailed the account username with password reset instructions."},{"id":"reply-19-21","title":"Account Activated / Temporary Password Email","category":"Accounts and Registration","audience":"Customer-facing","verify":true,"warning":"Confirm current activation and temporary-password process.","text":"I have activated your account.\nAn email was sent to your email address with a temporary password to user (name) with notification of account status change.\nThe system will force you to change your password when you log in."},{"id":"reply-23-23","title":"Court Maps Registration Guidance Sent","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Emailed guidance on registration & how to- file documentation to an existing case as it pertains to the process to obtain Court Maps registration."},{"id":"reply-25-26","title":"Cannot Forward Filing to Clerk or Judge","category":"Clerk and Docket Boundaries","audience":"Customer-facing","verify":false,"warning":"","text":"This is your notice that I cannot process the information from your email to your case, forward to the Clerk of the Courts, nor to the Judge.\nYour options are to file in person, by mail, or use the instructions below to file to your case."},{"id":"reply-28-28","title":"Filer Self-Resolved","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"The filer has self-resolved and will contact the portal again if assistance is needed."},{"id":"reply-30-30","title":"Domestic Relations / Family Classification","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Domestic Relations/Family (DR)"},{"id":"reply-32-32","title":"Voicemail Left","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Left a voicemail message with call back information."},{"id":"reply-34-34","title":"Spoke With Filer","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"spoke with filer to determine the information they needed."},{"id":"reply-36-39","title":"Portal Cannot Provide Docket Access","category":"Clerk and Docket Boundaries","audience":"Customer-facing","verify":false,"warning":"","text":"The e-filing portal website is not the county clerk or an entity that can give access to the docket, nor its filings\ndue to the legal limitations we are to work within.\nPlease use the county clerk's website to pull up the docket.\nIf you are not able to access the document(s), you may need to contact the clerk to ask what their procedure is to request access."},{"id":"reply-41-43","title":"My Submissions and Clerk Docket Processing","category":"Filing Status","audience":"Customer-facing","verify":false,"warning":"","text":"If you open your portal account, scroll to the upper right, and click on My Submissions, it will give you the status of your filings.\nThis means the clerk has accepted your filings and will upload the images to the docket once it travels through their system.\nThe e-filing portal does not auto upload directly to the docket. The uploading is a function completed by the Clerk of the Courts office."},{"id":"reply-45-47","title":"Request Filing Number From Service Email","category":"Information Requests","audience":"Customer-facing","verify":false,"warning":"","text":"Please advise of the filing number that was on the service of court documents email that you received.\nI need to make sure this is not a clerk or judge pulling information from their internal database, instead of the portal.\nIf there is no filing number at the upper left of the document in the email you received, it is not a portal issue, and you will need to work with the Clerk of the JA to get it sorted."},{"id":"reply-49-55","title":"Docket-Access Investigation Questions","category":"Information Requests","audience":"Customer-facing","verify":false,"warning":"","text":"To assist you with this issue. I need the following information:\nCounty the case is being filed in:\nIs this a new case or existing?\nIf existing, what is the case number?\nDoc# from the docket you are trying to access with description of document:\nYour attorney's bar#:\nVerify the website address you are using to try and access the docket from:"},{"id":"reply-57-63","title":"Spanish-Speaker Intake Information","category":"Language Assistance","audience":"Internal note","verify":false,"warning":"","text":"For the designated language-assistance team doing the Spanish speaker needed.\nPlease contact and gather information.\nFull name:\nemail:\nCounty case is filed in or will be filing in:\nCase number if one exists (or citation# if traffic):\nType of assistance needed:"},{"id":"reply-65-65","title":"Troubleshooting Sent","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Emailed troubleshooting / alternative steps for the encountered issue."},{"id":"reply-67-67","title":"eService Removal Instructions Sent","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Emailed eService removal instructions when hand keyed in by another party"},{"id":"reply-69-69","title":"Adyen Payment Information Sent","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Emailed the Adyen drop in payment processor information"},{"id":"reply-71-71","title":"Issue Escalated to Analyst Team","category":"Escalation and Follow-Up","audience":"Customer-facing","verify":false,"warning":"","text":"Your reported issue has been turned over to the analyst team. As soon as I have a resolution for you, I will contact you."},{"id":"reply-73-73","title":"Portal Service Desk Team Pinged","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Pinged portal service desk team asking for a response to post"},{"id":"reply-75-75","title":"Correction Queue Instructions Sent","category":"Internal Ticket Notes","audience":"Internal note","verify":false,"warning":"","text":"Emailed corrections queue tips and instructions"},{"id":"reply-77-77","title":"Waiting for Fee to Be Added","category":"Corrections and Fees","audience":"Customer-facing","verify":false,"warning":"","text":"As soon as team can add the fee in, I will notify you so you can correct and resubmit the filing."},{"id":"reply-79-79","title":"Do You Still Need Assistance?","category":"Escalation and Follow-Up","audience":"Customer-facing","verify":false,"warning":"Incomplete source fragment; complete before sending.","text":"Do you still need assistance? If so,"},{"id":"reply-81-81","title":"DIY Alternative: File a Court Document","category":"Filing Guidance","audience":"Customer-facing","verify":true,"warning":"References outside search engines; review before use.","text":"Instead of using the DIY, you can also have your response formatted as a court document (see google or other search engine, and use the file to existing case instructions)"},{"id":"reply-83-89","title":"Filing-Instruction Intake Questions","category":"Information Requests","audience":"Customer-facing","verify":false,"warning":"","text":"The following questions will help me to determine which instructions you may need to use to file.\nAre you trying to use the DIY with Interview module on the website?\nAre you filing a new case or to an existing?\nWhat county:\nIf new- What type of case are you filing for:\nCase# if existing:\nWhat is the name of the document you want to file?"},{"id":"reply-91-94","title":"Case, County, and Bar Number Request","category":"Information Requests","audience":"Customer-facing","verify":false,"warning":"","text":"Please send back the following information for me to be able to assist you:\nCase number:\nCounty filed in:\nYour attorney's bar#:"},{"id":"reply-97-98","title":"First-Come Response-Time Notice","category":"Openings and Closures","audience":"Customer-facing","verify":true,"warning":"Time-sensitive response estimate.","text":"We respond to tickets/request/issues (created by email/voicemail) on a first come, first serve basis, and in the order it was received.\nAt this time, our response is 24 hours out."},{"id":"reply-100-106","title":"Confidential Case / Summons Fee Limitation","category":"County or Case-Specific","audience":"Customer-facing","verify":true,"warning":"Confirm current confidential-case and county fee process.","text":"You will need to contact the clerk’s office for assistance with this issue.\nCurrently, the Portal will not allow you to select a party you are filing behalf of on confidential cases as no parties display.\nThis is a requirement when there is a filing fee and unfortunately, no way around it.\nThis has been brought to our attention, and we are working on ways to correct this issue.\nThe county will need to allow you to file your Summons under a different doc type that does not charge a fee and then accept payment for the\nsummons fee outside of the Portal.\nPlease let me know if you have any further questions."},{"id":"reply-108-111","title":"Resolved FCCC Network Issue Notice","category":"Outages and Delays","audience":"Customer-facing","verify":true,"warning":"Incident-specific legacy notice.","text":"Yesterday, the Florida Court Clerks & Comptrollers (FCCC) were experiencing network issues affecting several of our key systems,\nincluding CCIS, ePortal, eCLERC, MyFloridaCounty, and Civitek Jury applications.\nOur IT Operations team has resolved the issue and all systems are operating.\nWe did post this on the website yesterday:"},{"id":"reply-113-115","title":"Technical-Issue Assistance Delay","category":"Outages and Delays","audience":"Customer-facing","verify":true,"warning":"Incident-specific response delay.","text":"Hello,\nI apologize, but due to the technical issues the portal experienced yesterday, we do not have anyone available to walk you through the filing or to contact you to assist with your issue for at least 3-4 business days.\nThank you for your patience."},{"id":"reply-117-117","title":"Generic Instructions / Dropdown Limitation","category":"Clerk and Docket Boundaries","audience":"Customer-facing","verify":false,"warning":"","text":"Please use the generic instructions below to file. We cannot give you exact information on what drop downs to use, because legally, we are limited to the amount of information we can provide."},{"id":"reply-119-121","title":"Pending-to-Active Temporary Password","category":"Accounts and Registration","audience":"Customer-facing","verify":true,"warning":"Shared-password language has been redacted in this hosted build.","text":"An email was sent user with a notification of account status change from \"Pending\" to \"Active\".\nOn your next log in, the system will force you to change the password.\nThe temporary password: [REDACTED — verify the current procedure]."},{"id":"reply-123-125","title":"Hillsborough HOVER and Docket Images","category":"County or Case-Specific","audience":"Customer-facing","verify":true,"warning":"County-specific procedure may change.","text":"Hillsborough may have you access the docket through their system called HOVER from their website.\nI have seen a lot of dockets through the e-filing portal where the images for filings do not appear on the docket.\nThis is a Clerk action, not a portal action. If you are able to get to the docket and are not able open the image icons next to the description, please see the below restrictions."},{"id":"reply-127-132","title":"Bilingual Translator Call Introduction","category":"Language Assistance","audience":"Customer-facing","verify":true,"warning":"Adapt staff name and current routing.","text":"Hello,\nMy name is [staff name]. I am calling from the Florida Courts e-filing website.\nWill you need a translator for this conversation? If yes, I will turn your call over to a Spanish speaker, who will call you back for information.\nHola,\nMi nombre es Débora. Llamo desde el sitio web de presentación electrónica de los Tribunales de Florida.\n¿Necesitarás un traductor para esta conversación? En caso afirmativo, le pasaré la llamada a un hablante de español, quien le devolverá la llamada para solicitar información."},{"id":"reply-134-135","title":"Spanish-Speaker Task Note","category":"Language Assistance","audience":"Internal note","verify":false,"warning":"","text":"task for the designated language-assistance team\nneed information to be gathered by Spanish speaking personnel"},{"id":"reply-138-141","title":"Mandatory Auto-Checked eService Filer","category":"eService","audience":"Customer-facing","verify":true,"warning":"Confirm current eService protocol.","text":"Emailed the explanation of the new eService protocol in place for auto checking filer for service.\nThe e-filing portal has made a new change that now affects the eService list.\nThe protocol now is that the portal will automatically check you, the filer from the service list for filings being submitted via the eportal website MyFLCourtAccess.com\nThis is now a mandatory requirement with no option to opt out."}],"registrationText":"Main software:\nIvanti- pull tickets (Microsoft Edge)\nRAC- the admin side to look up accounts& filing information (Microsoft Edge)\nSQL- runs scripts to pull \"other\" information (Stand alone, needs no web browser)\nFiling Website of portal- MyFLCourtAccess.com (Google Chrome)\nCCIS: to view case docket / filings / parties (Microsoft Edge)\nTPE: for accounting stuff. Looking up charges by account number, amount and dates. (Microsoft Edge)\nFlorida Bar Website (Google Chrome)\nThe way I have my system setup.\nLaptop-Monitor-Monitor\nLaptop On my far left (Only running SQL)\nLeft monitor: All my programs I work in Edge\nRight monitor: All my Programs in Chrome\nWorking tickets (Registration)\nSet the dropdown to Portal Service Desk All Open Tickets\nGrab a ticket (Click on the incident#)\nAssign the ticket to yourself\nUse the dropdown to choose filer role (Attorney or PHV Attorney?)\nClick SAVE immediately\nUpdate the dropdowns and boxes beneath the Description box\nUpdate the Summary line to say Registration (Attorney name)\nSAVE\n5. Open the email or attachment on the ticket to view any additional info like address & phone\nCreate a NEW user / updating the Customer (top left)\nFill in name, email, phone\nChange the Organizational Unit to EFI (Efilers)\nUse the dropdown to choose filer role\nSAVE\nIf you could not see the address from the email they sent in, you can go to\nRAC- bring up to view the pending registrations.\nDouble click the line to open the request, which should then allow you to grab the address / phone info\nThen add address info at the bottom left.\nThen click the Copy to Mail button for the information to be pulled over to the right as well.\nThen click Save\nGo into RAC- Menu- Security- Registration Applications\nClick the line that person is on, if approved, then click the green check mark\nIf the application is rejected, you would click on the red X and enter your reason and save.\nIn the Ivanti ticket- email the person the reason for the rejection.\nThen resolve the ticket.\nIf approved, the system should send them an email to complete their registration.\nEmail out of the ticket letting the filer know they are registered and may have to complete the registration and to look for the email.\nIf they do not receive the email, they will need to email support@MyFLCourtAccess.com\nResolving the ticket:\nChange the status to Resolved\nAdd your resolution notes.\nUse the dropdown to sect your Cause Code.\nSave the ticket and you’re done.","sourceSections":[{"id":"verb-1","title":"Registration for E-Filing Portal Website Access","category":"Verbiage Source","status":"Verify before use","text":"Please do not register from a phone or tablet- it may affect functionality.\nPlease type the website address: myflcourtaccess.com\nCreate an Account:\nTo begin the account creation process, click on either E-Filing Portal in the menu bar or Log in now!\nThat will take you to the welcome page to the Portal.\nSelect your filer role from the drop down and click on the Register button.\nIf you are not an attorney and will be representing yourself: Self-Represented Litigant\n**Note: If you are an out of state attorney without a Florida Bar number, please visit: FloridaBar.org on Pro Hac Vice rules and regulations.\nFill out all of the information required.\nBe careful to look at the instructions for choosing a username/password:\nYour password must be between 6-16 characters.\nDo NOT use hyphens, underscores, nor &^%*() +.\nMake sure to scroll down and click on the register button.\nOnce you have registered, scroll up to the upper right corner and Click on the Sign Out hyperlink.\nIf you skip this step, you may have an issue logging back in.\nThen sign back in using your information.\nYou may receive an email to verify you have completed the process. Check your junk/spam if not in your inbox.\nRegistro para acceder al sitio web del portalhill de presentación electrónica\nPor favor escriba la dirección del sitio web: myflcourtaccess.com\nCrear una cuenta:\nPara comenzar el proceso de creación de cuenta, haga clic en Portal de presentación electrónica en la barra de menú o ¡Inicie sesión ahora!\nEso lo llevará a la página de bienvenida del Portal.\n1. Seleccione su rol de declarante en el menú desplegable y haga clic en el botón Registrarse.\n2. Si no es abogado y se representará a sí mismo: Litigante autorepresentado\n**Nota: Si es un abogado de otro estado y no tiene un número de Colegio de Abogados de Florida, visite: FloridaBar.org en Pro Hac Vice.\nComplete toda la información requerida.\nTenga cuidado de leer las instrucciones para elegir un nombre de usuario/contraseña:\nSu contraseña debe tener entre 6 y 16 caracteres.\nSin guiones ni guiones bajos, sin &^%*()\nAsegúrese de desplazarse hacia abajo y hacer clic en el botón de registro.\nUna vez que se haya registrado, desplácese hasta la esquina superior derecha y haga clic en el hipervínculo Cerrar sesión.\nRevisa tu correo electrónico para completar el proceso.\nComplete your registration You will receive a follow-up email that contains a link to activate your account. This email will be sent to the email address that you have registered with The Florida Bar. You must be able to access that account and know the answer to your security question to activate your account. You will receive the account activation email you have registered with The Florida Bar.\nPlease activate your account within 72 hours or it will be deleted from the portal, and you will have to repeat the step to register."},{"id":"verb-2","title":"Funky Username – (Probably corrupted from their browser?)","category":"Verbiage Source","status":"Verify before use","text":"It looks like your username needs to be reset. Right now, it reads: ******\nI can change it back to what it was before if you remember it. Keep in mind that you cannot exceeuse special characters.\nOtherwise, I show the account is active."},{"id":"verb-3","title":"Roles that cannot initiate a filing in the Portal","category":"Verbiage Source","status":"Verify before use","text":"Based on your filer role as a \"Process Server\", you cannot initiate cases.\nYou can create a self-representative litigant account in order to file this type of case."},{"id":"verb-4","title":"Password Reset / Inactive/Locked message for portal account","category":"Verbiage Source","status":"Verify before use","text":"**The instructions below are only for the website MyFLCourtAccess.com\n**Do not try to file from a phone or tablet. You cannot use the Safari web browser for our website; it will not work**\nThank you for contacting the MyFLCourtAccess.com website Help Desk.\nI do show the account as active.\nThe system will give an “inactive” message when you have input the incorrect username and/or password.\nWhen receiving the message: locked- is when the incorrect password or username has been entered more than 3 times.\nTo reset your password, enter your Current username:\nDelete the current password (if shown)\nClick on the “Forgot Password” button\nThis will send you an email link with a temporary password.\nPassword must be between 6 and 64 characters, with at least 1 number.\nPlease do not use underscores or hyphens, do not use ^&*() +\nUsername and passwords ARE case sensitive!\nOnce you have gained access, you may need to change the password before closing out of the site.\nIf needed, please make sure you go into your profile, update address, phone and email address information.\nScroll to the bottom to click on the Update button.\nThen, make sure to scroll to the top right of the webpage and click SIGN OUT.\nIf you do follow that step, it may not keep your changes.\nFor Attorneys:\nThe email will be sent to the email you have listed on the Florida Bar website.\n** Because we protect accounts for the account holders, we are unable to share the portal log in information, an email has been sent to the account holder with their credentials\nPlease get with the attorney for the information.\nIf you are having trouble logging into your account, I am happy to assist you. If you want to create another account, please be aware that you will not have access to any cases associated with your existing account(s) until you have filed to them using the new account. Please let me know how you would like to proceed.\nUsername:\nAssociated Email:\nAttorney Bar Number Needed:\nYour email address was not in the file that the Florida Bar provided to us, and this is required for an account with the E-Filing Portal to register.\nWe were able to verify that you are indeed a Pro Hac Vice attorney and circumvented the email address requirement by creating an account on your behalf and rejecting your original registration.\nWe have activated your account, and if you have any issues with access, please contact us.\nGood afternoon,\nWe have approved and activated your request for registration on the E-Portal site.\nYou should receive two emails. A thank you and one with a link you will need to follow to access the portal and sign up. The link will be sent to the email below that is stated on the Florida Bar website.\nYou have been approved on the E-Portal site for access.\nMensaje de restablecimiento de contraseña / inactivo / bloqueado para la cuenta del portal\n**Las instrucciones a continuación son solo para el sitio web MyFLCourtAccess.com\n**No intente presentar desde un teléfono o tableta. No puede utilizar el navegador web Safari para nuestro sitio web; no funcionará**\nGracias por ponerse en contacto con el servicio de asistencia del sitio web de MyFLCourtAccess.com.\nMuestro la cuenta como activa.\nEl sistema dará un mensaje de \"inactivo\" cuando haya ingresado el nombre de usuario y/o contraseña incorrectos.\nAl recibir el mensaje: bloqueado: es cuando la contraseña se ha ingresado/intentado más de 3 veces.\nPara restablecer su contraseña, ingrese su nombre de usuario actual:\nEliminar la contraseña actual (si se muestra)\nHaga clic en el botón \"Olvidé mi contraseña\"\nEsto le enviará un enlace de correo electrónico con una contraseña temporal.\nLa contraseña debe tener entre 6 y 64 caracteres, con al menos 1 número.\nPor favor, no use guiones bajos o guiones, no use ^&*() +\n¡El nombre de usuario y las contraseñas DISTINGUEN entre mayúsculas y minúsculas!\nUna vez que haya obtenido acceso, deberá cambiar la contraseña antes de cerrar el sitio.\nAsegúrese de ingresar a su perfil, actualizar la dirección y la información del teléfono si es necesario.\nDesplácese hasta la parte inferior para hacer clic en el botón Actualizar.\nLuego, asegúrese de desplazarse hasta la parte superior derecha de la página web y haga clic en CERRAR SESIÓN.\nSi sigue ese paso, es posible que no conserve sus cambios."},{"id":"verb-5","title":"Profile Changes","category":"Verbiage Source","status":"Verify before use","text":"To update the information on your e-filing portal account profile: (including email address)\n1. Log into your account on the website MyFLCourtAccess.com\n2. Go to the MY ACCOUNT dropdown\n3. Click on MY PROFILE\n4. Click on the USER DETAILS tab\n5. Make any changes needed\n6. Scroll to the bottom and click on UPDATE\n7. Please make sure to scroll to the top of the webpage and click SIGN OUT.\nIf you don’t follow those steps, it may not keep your changes.\nPlease be advised that making changes to your profile does NOT update the emails on the e-service list for any cases filed previously, nor does it update any information to the Clerk of the Courts.\nIt is your responsibility to contact that county and or go to your account on all their websites you have an account with to update your information.\nIf you want to update or remove your email from cases, you can use the eService Maintenance instructions attached to update, and the removal instructions attached for removal.\nIf you are listed on the service list with one of these icons (in black), you will not be able to remove yourself from the list and will need to email: support@myflcourtaccess.com with the following information: if multiple cases, please enter the information in an excel spreadsheet and attach to the email request:"},{"id":"verb-6","title":"I filed, what are my next steps?","category":"Verbiage Source","status":"Verify before use","text":"The E-filing Portal help desk, support@myflcourtaccess.com only provides Navigational / Technical Support for the website MyFLCourtAccess.com for the submission (uploading) of documentation that you have ready to file to create a case, or to an existing case.\nWe do not provide Clerk of Courts procedural information, nor are we able to advise or provide you with the form(s) needed to be filed or where to find them.\nWe cannot advise on what the steps are or case status.\nI would suggest going to the Clerk of the Courts website to read everything you can on the rules and procedures for your case type."},{"id":"verb-7","title":"On the Case Parties/Roles set up:","category":"Verbiage Source","status":"Verify before use","text":"Do NOT use punctuation when entering information\nFor the role of Plaintiff/Petitioner:\nAlways check the boxes to the right Primary Party & Filed on Behalf of\nFor the role of Defendant/Respondent: Only check the box Primary Party\nYou do not check any boxes for Attorney (if one is listed & filing)\nIf applicable:\nFor the role of Decedent: Only check the box Primary Party\nIf you use a business/organization name, you can only input up to 50 characters.\nThis includes empty spaces.\nSign In Issues:\nI suggest making sure that when/if the auto saved information fills, make sure there is no space between the last character and the cursor.\nAlways be sure to Sign Out of the website by clicking on the sign out hyperlink in the upper right corner of the webpage.\nIf you do not and you try to sign back in, it may think you are already signed in and not let you again.\nDo you have more than 1 account? Maybe you are trying to access an account with a different Username/Password."},{"id":"verb-8","title":"Documents not showing on the docket","category":"Verbiage Source","status":"Verify before use","text":"Unfortunately, we are not the party responsible for uploading filed information to the docket.\nThis is an action completed by the Clerk of the Courts system.\nThe e-filing portal sends the documents you upload to the clerk.\nThe clerk then processed through their case management system, then dockets the forms you submitted to the docket.\nPlease contact the Clerk of the Courts office in the county the case is filed in to ask\nif something is wrong with the docket or prohibiting documents from showing on the case."},{"id":"verb-9","title":"Work Bench Explanation","category":"Verbiage Source","status":"Verify before use","text":"Think of the work bench like your web browsers history. It keeps track of cases you have pulled up to look at or had started to file to.\nIt doesn't mean anything more than that.\nAfter 5 business days, anything that is listed on the workbench removes itself.\nOnly filings submitted through the portal that have been given a filing number (not submission number from the workbench) will be listed under My Submission/Cases.\nThe listing on the workbench does not mean it has not been filed to the Clerk.\nNor does it hold a date / time stamp from an attempt.\nPlease go to the upper right corner of the website. Click on “My Submissions\".\nIf you do not see your filing (look at the dates) that means your submission was not processed and you will need to start the filing again.\nIf there is an issue with anything you have submitted to the Clerk, and it has been kicked back, it will be listed in your Alerts.\nIf you started filing and saved it to the workbench, I suggest you not pull it from the workbench, and to start your filing over (if it was not in the submitted list) and do not to use it."},{"id":"verb-10","title":"Can I file my case on the website?","category":"Verbiage Source","status":"Verify before use","text":"Thank you for contacting the MyFLCourtAccess.com website Help Desk.\nSupport for the website MyFLCourtAccess.com is limited to only providing navigational & technical guidance for the purpose of filing documentation that you have ready to file to create a case, or file to an existing case.\nFor any questions outside of navigating the website to file documentation, please contact your Clerk of the Courts office.\nPlease be advised that the E-Filing portal website MyFLCourtAccess.com is not the Clerk of the Court or the District Court of Appeals.\nInstructions are not exact, and we are unable to tell you exactly which drop downs or forms are needed to file, as we are limited by legal restrictions and cannot offer legal advice.\n1. What type of case are you filing?\na. Circuit Civil\nb. County Civil (Small Claims under $8,000) (types less than $50,000) (Eviction)\nc. Domestic Relation/Family\nd. Probate\ne. Juvenile Dependency\nf. Adoption\ng. Domestic Violence / Stalking / Cyber Bullying\n2. What County are you filing in?\nSome counties will have different requirements, procedures, and forms.\n3. What forms are needed?\nPlease visit the Clerk of the Court’s website for the county you are filing your case in for information on procedures, forms that are required to be filed, and to determine the Division, Case Type, and Sub Type you will need to file under.\nMost cases in Circuit or County Civil courts will require a “Complaint” or “Statement of Claim” form.\nMost cases in Family/Domestic Relations, a Petition is to be the first document you upload, followed by others that may be required.\nProbate: varies. Check with the Clerk's website to determine what is needed.\nOnce you have the forms needed to file, you can use the below for guidance.\nEl servicio de asistencia del portal de presentación electrónica, support@myflcourtaccess.com, solo ofrece asistencia técnica y de navegación para el sitio web MyFLCourtAccess.com\npara el envío (carga) de la documentación que esté listo para presentar para crear un caso o para un caso existente.\nNo proporcionamos información sobre el procedimiento del caso, ni podemos asesorarlo, ni proporcionamos los formularios necesarios para presentar ni dónde encontrarlos.\nLas instrucciones no son exactas debido a que la ley nos limita a lo que podemos aconsejar.\nNo podemos indicarle exactamente qué menús desplegables o formularios necesita para presentar, ya que no podemos ofrecerle asesoramiento legal.\n1. ¿Qué tipo de caso está presentando?\na. Civil de Circuito\nb. Civil de Condado (Reclamaciones Menores de menos de $8,000) (tipos menores de $50,000) (Desalojo)\nc. Relaciones Domésticas/Familiares\nd. Sucesiones\ne. Dependencia Juvenil\nf. Adopción\ng. Violencia Doméstica\n2. ¿En qué condado está presentando su caso?\nAlgunos condados tienen diferentes requisitos, procedimientos y formularios.\n3. ¿Qué formularios se necesitan?\nVisite el sitio web de la Secretaría del Tribunal correspondiente al condado donde presente su caso para obtener información sobre los procedimientos, los formularios necesarios y determinar la División, el Tipo de Caso y el Subtipo bajo el que deberá presentarlo.\nLa mayoría de los casos en los tribunales civiles de circuito o de condado requieren un formulario de \"Demanda\" o \"Declaración de Demanda\".\nEn la mayoría de los casos de Relaciones Familiares/Domésticas, el primer documento que debe presentar es una Petición, seguida de otros que puedan requerirse.\nSucesiones: varía. Consulte el sitio web de la Secretaría para determinar qué se necesita.\nTenga en cuenta que el portal de presentación electrónica MyFLCourtAccess.com no representa a la Secretaría del Tribunal ni al Tribunal de Apelaciones del Distrito."},{"id":"verb-11","title":"Pro Hac Vice- Register & Filing","category":"Verbiage Source","status":"Verify before use","text":"The best place to start is the FloridaBar.org website to see what the PHV procedure is for obtaining a PHV FL Bar number.\nTo register and file as a PHV on the MyFLCourtAccess.com website, you must have been issued a Florida Bar number.\nOnce you have the bar # you can then register on our website 48-72 hours after the bar number being issued. If you try to register before that, your registration may be rejected because it is not yet in the system to file to cases\nThe County Clerk may require you to pay a $100 PHV fee.\nNew Attorney to case/ PHV / NOT showing up in My Cases\nAn attorney will not be able to access or view any case dockets on the Florida Courts E-Filing portal that they are not the Attorney of Record for AND if they have not filed electronically to the case through the website.\nCases are not automatically added to your My Cases, nor are you automatically added to the service list. You must file to the case.\nOnce you submit the filing and the Clerk has moved the filing from Pending to Filed, it will then show up under your \"My Cases\".\nIf you are a Pro Hac Vice attorney, being admitted to the case does not automatically allow you to access the case docket through the e-filing portal.\nIf you are not going to be the attorney of record, and you are not filing to the case, please contact the Florida attorney you are working with and ask for them to add you to the service list on the next filing.\nWhen filings are done after that point, and the filer checks your box (it is up to the filer to decide whether to check you for service because it is not done automatically to everyone on the service list) you will get an email with a copy of what has been filed to that case.\nWarning, if you leave the email untouched, or it ends up in your spam for more than 14 days, you can no longer access the documents from the email. We usually tell eService recipients to open and download the filings immediately so that doesn't happen."},{"id":"verb-12","title":"Changes to Attorney Portal account when moved to another firm (when emails do not match FL Bar website)","category":"Verbiage Source","status":"Verify before use","text":"An e-portal account never belongs to the law firm. It always belongs to the attorney no matter where they go unless it was a government email address like a SAO or PD.\nOn the Florida Bar website, it has you listed as:\nIf that is not correct, please update it. I cannot send you the email that will have your account username and password reset information until that has been done.\nPlease email me at [internal staff email removed] with that information.\nI will close this ticket and look for your email.\nIn your email, state the following:\nMy Information on the FloridaBar.org website has been updated (it may take 24-48 hours for that to happen)\nList your bar#\nNew email address:\nI will then send you an email with all the information needed to get in and update your profile.\nSelf-Represented Litigant & Non-Attorney- Case Status & Access\nMyFLCourtAccess.com cannot give access to self-represented filers to view their case docket or filings made to your case through this website.\nYou cannot get case updates via this website.\n**You may only file to your case through this website**\nWe do not \"link\" your case docket to your portal account.\nOnly documents you filed through this website are viewable through your Email Log under your My Account tab, 14 days after the clerk has accepted the filing(s).\nDocuments that others have filed into your case, the links are only accessible for 14 days if you were selected to be included in the eService email that was sent out, which has a link you can click on to view and download the documents.\nIf you were not selected (check your junk/spam) then you will need to access from the Clerk of the Courts website.\nIf it is beyond the 14 days, to access case information and/or case status, you will need to visit the Clerk of the Courts website in the county your case is filed in.\nIf you are unable to access information from their website, you may have to make a formal request on their website from the case.\nIf you want to file documentation to your existing case, you can use the File to Existing instructions below."},{"id":"verb-13","title":"Request to consolidate/merge accounts","category":"Verbiage Source","status":"Verify before use","text":"We show that you have ?# accounts:\nPortal user# ????? Primary email\ntied to the organization- ?\nUsername:\nPortal user# ???? Primary email:\nnot tied to any organization?\nUsername:\nWe do not merge or consolidate accounts. However, we can make one/or? of them inactive.\nAlso, if you have filed using one of the emails you no longer wish to use, but they were used on cases for eservice in the MyFLCourtAccess.com website,\nyou may want to use the Manage My Eservice instruction attached to this email to change the email address they are going to or to update the service list.\nYou should be able to make the changes to any cases you added yourself to.\nHowever, if you were hand keyed in by a Clerk or Judges office, you will need to make arrangements with their office on updating the email address.\nThis can be determined by the icon shown next to your name on the service list:\nForeign Judgements\nIn reference to your request for filing for divorce. Since you came from another state and the other party lives in another state than the one you live in, you can look up this suggestion on Google or Bing: File for divorce if spouse lives in a different state.\nThat is a good starting point. If you do decide to file in Florida, visit your county's clerk of court for the paperwork information. Online resources are great for trying to figure out what has to be filed and, in the order that they need to be filed.\nIf you decide to file in Florida, you can sign up for the E-Filing portal (myflcourtaccess.com) so that you can start your case and file paperwork."},{"id":"verb-14","title":"Please contact the Clerk of the Court","category":"Verbiage Source","status":"Verify before use","text":"Thank you for contacting the E-Filing Portal website MyFLCourtAccess.com.\nUnfortunately, I am unable to assist you.\nThe E-filing Portal help desk, support@myflcourtaccess.com only provides Navigational and Technical Support for the website MyFLCourtAccess.com\nfor the submission (uploading) of documentation that you have ready to file to create a case, or to an existing case.\nWe do not provide case procedural information, nor are we able to advise you on which forms need to be filed or where to find the form(s).\nPlease be advised that the E-Filing portal website MyFLCourtAccess.com is not the Clerk of the Court or the District Court of Appeals.\nWe are unable to:\n1. Verify your court date.\n2. Review / pull / give access to documents / status of case, issuance of summonses / provide copies / explain case procedure.\n3. Provide legal counsel.\n4. Confirm your Application for Indigence approval.\n5. Unlock documents from the docket.\n6. Assist with Zoom, telephonically connect, or reschedule your Zoom meeting.\n7. Provide where to find information on what forms you need to file.\nWe do not offer or have access to forms to send to you.\nIf you are not sure of the form(s) you need or how to complete your forms correctly, it is recommended that you seek legal counsel to assist you.\nFor help with your request / issue / questions, please contact or visit the website for the:\nClerk of the Courts in the county your case will be or has been filed in or visit their website.\nIf you are filing in or with the District Court of Appeals\nThe District Court of Appeals for the jurisdiction filing/filed in or visit their website.\n*Please note that Florida law (F.S. 28.215) prevents our staff from providing legal advice. .\nI am not an attorney and cannot provide legal advice. Nothing contained in this correspondence is intended to be, nor should it be, considered as such."},{"id":"verb-15","title":"Data Collecting when something wrong happens on the website","category":"Verbiage Source","status":"Verify before use","text":"Thank you for reaching out. We have noticed a few offices experiencing slowness with the site. We are being asked to collect the following data to help pinpoint where the issue may be.\nDates experiencing slowdowns:\nFiler Role: (Attorney, Law Enforcement...)\nBrowser being used and version: (Microsoft Edge, Google, Firefox)\nWho is your internet provider?\nDescription of issue:\nLast time your browser was updated?\nName: / Organization Name:"},{"id":"verb-16","title":"Change Docket Information/ Rescind or Remove from","category":"Verbiage Source","status":"Verify before use","text":"If your filing was incorrect and/or docketed to the case with incorrect information and should be removed or changed, please contact the Clerk of the Court as to what their procedure is.\nContact the Clerk to check if they have not accepted or filed your submission.\nIf the filing has not been “Filed” to the docket:\nHave the filing moved to the correction queue for you to correct it then re-file to the case.\nHave the filing rejected all together.\nIf the Clerk has accepted the filing and the documents have been added to the docket:\nCall the clerk to inquire on what their procedure is to have it corrected or removed from the docket.\nOnce the clerk has updated the docket, you can do 1 of 2 things so that the information gets corrected in your My Cases on the portal:\nRe-file to the case through the portal using the E-filing map option, not from\nthe My Cases. This will show the case parties correctly after submitting.\nOR\nSend an email to Support@myflcourtaccess.com with the case#, county, and ask to mirror the information listed on the docket header for name:\n(After the clerk has made the changes to the docket)\nUnfortunately, we only handle the navigational & technical side of the E-Filing Portal, and we do not have the ability to review, change or send copies from submitted filings. The Clerk's office handles and reviews all filings and should be able to help you with your request."},{"id":"verb-17","title":"How to correct when filed Under the Wrong Attorney","category":"Verbiage Source","status":"Verify before use","text":"We are unable to remove the case from under the incorrect attorney’s My Cases.\nYou will need to refile to the case under the correct attorney.\nLog in under the wrong attorney's account and remove them from the eService list. (see attached instructions)\nDouble check that the correct attorney is listed on the docket as the attorney of record.\nOtherwise, you will need to contact the Clerk of the Court to inquire as to what the procedure is for changing the AOR."},{"id":"verb-18","title":"Filed under the wrong county","category":"Verbiage Source","status":"Verify before use","text":"Pease refile to the case under the correct county.\nWe are unable to remove the filing from the docket that was done in the incorrect county.\nYou will also need to remove yourself from the eService list as well from the incorrect case.\nIf the filing was docketed to the case:\nPlease contact the Clerk of the Court's for the incorrect county to inquire as to what their procedure is for removing your filing from the wrong docket."},{"id":"verb-19","title":"Troubleshooting – Browsers","category":"Verbiage Source","status":"Verify before use","text":"If you still have trouble after that we recommend trying the trouble shooting information below:\n1. Sign out of the website using the Sign Out hyper link in the upper right corner.\n2. Clear the cache and cookies from your browser(s).\n3. Update your Edge or Chrome browser(s)\n4. Restart your computer"},{"id":"verb-20","title":"CourtMAPs","category":"Verbiage Source","status":"Verify before use","text":"See the word document explaining the procedure."},{"id":"verb-21","title":"Unknown Charges:","category":"Verbiage Source","status":"Verify before use","text":"I will need more information to assist.\nWhat type of payment was used (Credit, debit, ACH?)\nWhat is the last 4 of the payment account/card number?\nDate of Charge:\nAmount of charge:\nAny other numbers/verbiage from your statement?"},{"id":"verb-22","title":"My Cases- Case does not populate:","category":"Verbiage Source","status":"Verify before use","text":"If you click on My Cases, and in the Case Style box, insert the last name of a case party and click search, the case will populate for you to access or file to. If it does not, try the other case party or business name.\nAlso, look at the search options:\nCourt: leave blank if you are searching by last name.\nThen remove last name and search by county.\nInclude: (set this to all or active)\nCases per page: change to 1000.\n**Suggested filer use the alternate look up method to pull case forward from the My Cases search function or will need to file to the case for access if not done previously"},{"id":"verb-23","title":"Case Number Breakdown","category":"Verbiage Source","status":"Verify before use","text":"**The below is just an example. This is not your actual case number***\n16-2022-DR-001917-FMXX-MA\n16- The county\n2022- Year case was entered into the system\n2-Letter Division Identifier: DR/CA/CC/SC/CF/TR/CT/CJ/DP/GA/CP- Is the Type of Case\n001917- Is the Sequence Number\nFMXX- Is the Party identifier (most times you will not put this in except for certain Criminal CF cases)\nMA- Is the Branch Location (most times you will not put this in except certain Criminal CF cases)\nIf your search produces %%% signs in them, you have entered in the wrong information.\nIf you added the Party Identifier and Branch location, remove them, and try “SEARCH” again."},{"id":"verb-24","title":"Proposed documents in “Transmitted” status","category":"Verbiage Source","status":"Verify before use","text":"The filing is still in the transmitted status.\nOn filings \"transmitted\" to the Judge:\nPlease call the JA with the filing number (9-digits) to see if they call pull it from the Judicial Circuit Interface queue.\nHere is how proposed orders are supposed to move through the system:\nFiling is submitted.\nThen transmitted to the Judicial Circuit Interface.\nThe judge's office goes in and pulls the filing from the judicial circuit interface.\nThe judge signs off or denies the proposed order.\nThe Judge's office sends the denied or signed filing to the Clerk. (at the Judge's discretion what the exact procedure is, it may or may not go through the clerk)\nThe Clerk files to the docket if approved and signed.\nOr the judge’s office files directly to the docket.\nIf the Judge's office cannot find the filing, they may require you to refile.\nAlso, The Clerk does not always file the signed copy, nor does the judge always send the signed or rejections through the e-portal system. This means you will need to check the docket to make sure signed orders are not being missed. The Clerk of the Court’s have their own procedures in which they send out the signed orders if the Judge’s office does not process. You may want to call and check with the Clerk and or the JA on what their procedure is."},{"id":"verb-25","title":"Cannot make changes to the docket","category":"Verbiage Source","status":"Verify before use","text":"Unfortunately, we only handle the navigational & technical side of the E-Filing Portal, and we do not have the ability to review your case, make changes to or send copies from submitted filings.\nThe Clerk' of Court’s office handles the uploading of your filings to the docket once they have run it through their case management system."},{"id":"verb-26","title":"* Formatting /Conversion Issues resulting in:","category":"Verbiage Source","status":"Verify before use","text":"Loss of information when filing Indexes, Exhibit markers, Bookmarks, Page Numbers, etc.\n* Portal isn’t accepting the PDF files you are trying to upload.\nIf this contains the following, your file will need to be in PDF/a format (see attached document):\nTranscripts & Briefs\nContains bookmarks or indexing\nWe typically see these issues due to the way the files are being created or formatted.\n1. Using embedded fonts not recognized by the system.\n2. Not leaving the space needed in the margin area.\n3. The type of software / program being used for your conversion.\nWhen filing the type of files that have Headers / Footers, Page Numbering, etc., the PDF file is to be formatted / converted in a specific way.\nMargins and Print Area: It’s very important to stay within the guidelines, or the header/footers and page numbers will disappear as well as other information.\n**Transcripts with any indexing, bookmarks etc, MUST be in PDF/A 2-B format.\nPDF files shall be filed in a format capable of being electronically searched and printed.\nUnfortunately, we cannot correct or convert your files for you.\nI am listing some information below, as well as attaching the PDF FAQs to assist in helping you determine if there is a formatting issue you will need to resolve.\n1. No locked, secured or encrypted PDF files\n2. Do not scan in pages using a DPI larger than 300.\n3. The name you have given the file is incompatible.\nIf your file has special characters you will need to rename the electronic file.\nExample:\nif it looks like asd_812#.pdf, rename it, removing the unacceptable characters to something else like asd812.pdf\n4. The name of your PDF file cannot exceed 36 characters including blank spaces.\n5. The file was corrupted in transition from the original format to the format you currently have. Ex: Word to pdf or jpg to .docx\n6. The file page size is too large. instead of 8.5x11 it is 8.62x11.26 or any other size other than letter. (may need to check your software to undo any automatic settings that may be converting them a specific way other than what you require)\n7. Do NOT upload compressed or zipped files.\n8. When uploading a file, make sure it is completely uploaded before trying to add another document. (the 100% green bar needs to be gone and reflect a percentage number)\n9. Information entered is either incorrect or missed\n10. Remove ALL COLOR- the portal does not accept any color documentation including signatures, hyperlinks and email addresses.\n11. The maximum upload at one time, with all files combined cannot exceed 50mb for Lower Courts or 200mb for Supreme and Appellate Courts.\nThat means if you upload 4 documents and their combined size exceeds the maximum; your files will not upload.\n12. Formatting is not correct. ie: embedded fonts, margin errors, etc.\n13. ***NO VIDEOS / NO COLOR PICTURES, NO AUDIO RECORDINGS***"},{"id":"verb-27","title":"Documents will not upload- says 100% but can go no further","category":"Verbiage Source","status":"Verify before use","text":"What are the total mega bites for your filing? It cannot be over a total of 50mb.\nIf loading multiple documents, you need to wait for one to upload before trying to add another.\nIf either of those do not work, sign out of the portal using the Sign Out hyperlink in the upper right-hand corner.\nClear your browsers cache and cookies and update your browser.\nSign back into the website, and file all over instead of using the saved progress from the workbench."},{"id":"verb-28","title":"Florida Supreme Court Standards for Electronic Filing to the Courts","category":"Verbiage Source","status":"Verify before use","text":"3.1.14.2 Exhibits Lower Courts- shall not exceed a total of 50 MB in size.\nPlease read all the information below and attached to make your filing successful.\nIt is important to pay close attention to any embedded fonts used, margin restrictions, and how the file is formatted.\n**The 1st page of each pdf/a document will need to have the legal header with case number (If applicable) listed in the appropriate area- if applicable.\nEach exhibit accompanying a document shall be separately attached and denominated with a title referencing the document to which it relates. Each exhibit shall conform to the filing size limitation in Section 3.1.1. To the extent an exhibit exceeds the size limitation each portion shall be separately described as being a portion of the whole exhibit (e.g., Exhibit A, Part 1 of 5, Part 2 of 5, etc.).\nEach documentary exhibit marked for identification or admitted into evidence at trial shall be treated in accordance with Florida Rule of Judicial Administration\n2.525(d)(4) or (6), and then converted by the clerk and stored electronically in\naccordance with rule 2.525(a).\nMust be in pdf or pdf/a format. (except the order on a proposed order, that must be in word docx format)\nPlease do not file from a phone or tablet- it may affect functionality.\nYou cannot use the Safari web browser that is on most Apple/Mac devices.\nYour file must be in PDF or PDF/a format.\n***NO VIDEOS / NO COLOR PICTUREs*** Including the signatures.\nPlease call the clerk of the court in the county your case is filed in and ask how they want those submitted to them.\nThe page size cannot exceed 8.5 x 11\nIf you are scanning pages into a PDF, make sure they are at 300DPI\n*Portal will NOT accept:\nCompressed or zipped files.\nPDF files that in the name contain any special or odd characters such as:\nhyphens, underscores, or odd characters (%^&*( )=+) or web dings\nPDF file name exceeds 36 characters in length.\n“Locked” or “Secured” PDF files.\nWill not accept non-standard embedded fonts.\nCheck the formatting of margins.\nA combined total of 50mb is the maximum for a filing session.\nIf it exceeds that, once you submit, go back, and do another session to complete filing.\nFor Higher Courts- shall not exceed a total of 200 MB in size.\nThe aggregate size for the Appellate Court and The Florida Supreme Court cannot exceed 200 megabytes for one submission.\nSeparate the large document into multiple documents each under 50MB or for the FSC and the DCAs 200MB. Submit one Part 1 of 3 with\nthe first filing, Part 2 of 3 with the second filing, and Part 3 of 3 with the third filing which results in the complete document being filed.\nA filing can be up to 500MB (I believe) to the Florida Supreme Court and District Court of Appeal's. However, if the filing is larger than 100MB they will need\nto be served outside of the Portal. Filings are broken down into 10MB attachments and attached to the E-Service email.\nSince there can't be more than 10 attachments to the email.\nThe e-filing portal website can't handle E-Service for documents larger than 100MB.\nConfidential Filing (should be filed at the time of filing the sensitive information)\nPursuant to Florida Rule of Judicial Administration 2.420(d)(2), the filer of a court record at the time of filing shall indicate whether any confidential information is included within the document being filed; identify the confidentiality provision that applies to the identified information; and identify the precise location of the confidential information within the document being filed."},{"id":"verb-29","title":"Lawyer is Attorney Of Record- but not listed on docket (Cannot access documents)","category":"Verbiage Source","status":"Verify before use","text":"Looking at the docket, the Clerk's office has not added you/your/the attorney as the AOR.\nPlease contact the County Clerk's office, give them the case and filing number. Advise that they do not have you listed as the Attorney of Record even after your Notice of Appearance was filed, thus making you unable to access the documents through your portal account and that you have already spoken to the e-filing portal support service desk and was directed to contact them because only the Clerk's office can update the docket.\nOnce that is done, you should have access to the case through your portal account. Keep in mind there are some cases you will not be able to access even as the Attorney of Record.\nExample: Closed, Sealed, Confidential, Formal Probate or Locked files."},{"id":"verb-30","title":"Civil Cover Sheet Missing Error Message","category":"Verbiage Source","status":"Verify before use","text":"The error message says, \"Please review the following error(s) and correct them. The focus will be set to first error in the list: Document Information for Document #1 is not complete.\"\nI'm sorry you have run into an issue with your filing.\nOpen the filing from the correction queue. On the Case Information tab, make sure to scroll down and verifying the information. Once you get to the bottom of the page, click on next.\nFrom this tab on the case parties, does it have anywhere that says Edit? Click on the Edit for your (Petitioner) name.\nAt the very top, does the ROLE say Petitioner? Did you click the buttons to the right for Primary Party and Filed on Behalf of?\nIf not, do so here.\nScrolling down, look over the information, making sure the full name and address are listed. At the very bottom on the right, click save.\nNow for the Respondent, click edit. Make sure ONLY the Primary Party box is check marked. Scroll down double checking all of the information is filled out and at the bottom right click save.\nThis should generate a new Civil Cover sheet for you.\nIs the document listed under the Document Group/Type listing?\nIf so, click next.\nCheck mark those that need to receive e-service, click next.\nDoes it show you owes fees? If so, enter the information and click save/next.\nSometimes if you have paid a fee for the filing you are correcting, they will have already start the refund process and you would have to pay \"again\". You should receive a refund for the 1st filing in 1-5 business days depending on your county and banking institution.\nIf you are ready to submit the correction, Click submit.\nIf you continue to have this same issue, please contact me."},{"id":"verb-31","title":"How a filing is processed through the portal to the clerk:","category":"Verbiage Source","status":"Verify before use","text":"We do not manage nor upload your documents to the docket the clerk has created.\nThink of the portal as the electronic mail delivery. Once the Clerk takes the accepts the filing, the portal is then hands off.\nThe Clerk moves the filings through their case management system and uploads the images to the docket.."},{"id":"verb-32","title":"Confidential case access or filing information","category":"Verbiage Source","status":"Verify before use","text":"If a case is confidential or involves a minor, you may not be able to access the case docket from the MyFLCourtAccess.com website and will need to contact the clerk of the courts to obtain docket access.\nSince we are not the Clerk, we are unable to grant access or send copies.\nNote: All confidential, sealed, domestic violence, and most formal probate dockets are also NOT accessible from our website.\nWhen filing to these types of cases, case party names will not be displayed in the portal, are not searchable in your My Cases, and parties to file on behalf of are not always listed.\nThe portal will not allow for filing to confidential cases where parties are not listed and the filing has a related fee.\nIf there is a fee, the filing will need to be done in person, by mail or courier."},{"id":"verb-33","title":"Useful websites:","category":"Verbiage Source","status":"Verify before use","text":"I would recommend researching information on the websites: Help.FLCourts.gov & your County Clerk of the Court to see if there is any information that can answer your questions.\nWe do have a How-To area on the website MyFLCourtAccess.com\nBefore signing in at the top right, the How to drop down can take you to videos that show filing information such as the flow through the website.\nhttps://www.abafreelegalanswers.org\nhttps://www.pdf2go.com/convert-to-pdfa\n** Emailed Useful Website links to help aid in the research of forms and information\nThere is a ton of information on the internet, and there should be some information on the county's clerk of the courts website to help guide you as I can only offer technical assistance with the portal."},{"id":"verb-34","title":"Docket access","category":"Verbiage Source","status":"Verify before use","text":"Thank you for contacting the E-Filing Portal website MyFLCourtAccess.com.\nThe e-filing portal cannot provide copies of filings from the docket or eServiced documents.\nReasons why you may be unable to access dockets &/or filings via this website.\n(See one or more of the listings highlighted below)\nThe file is too large; this website will time out before the document can be opened. (Larger than 15-20 pages)\nThere is a lock or stop sign symbol for the document:\nThe file has been locked due to confidential or sensitive information.\nThe Portal does not have the ability to lock or unlock files nor have access to them.\nIf the case has /is a: disposition date, closed, sealed or confidential.\n(Even if you are the attorney of record- you will still be unable to access via your e-filing account)\nThe Clerk does NOT have you listed on the docket as the Attorney of Record.\nYou are not logged into the AOR account to be able to access the documents.\nIf this case is a Formal Admin Probate case. You cannot access those through your e-filing portal account.\nYou have NOT filed to this case through the e-filing portal as the Attorney of Record through your portal account.\nPlease visit the Clerk of the Court’s website in the county where the case is filed in and try to obtain it from their website’s case search.\nIf you’re unable to access the docket and their filings, you will likely have to use the Clerk’s request form (if they have one) from their website or sign up for an account to use their website. Please contact the Clerk of the Court in the county the case is filed in to inquire if the document is available and can it be sent to you in an alternative method or format.\nPlease note, the E-Filing Portal MyFLCourtAccess.com website is not the Clerk of the Court or The District Court of Appeals.\n**Referred to the Clerk for an alternative method of accessing filings not able to be accessed or viewed through E-Filing portal account and/or the Clerk website."},{"id":"verb-35","title":"When Payments aren’t processing at all","category":"Verbiage Source","status":"Verify before use","text":"Are you trying to use a saved payment? Amex, Visa, MC or ACH?\nLast 4-digits of card or account:\nHave you tried to hand key in the information and check the box at the bottom to Save payment for Future Use?\nWhen was the last time you successfully made a payment using that exact card?\nIs this a new card? Has the Bank name or Expiration date changed?\nHave you changed the username or password to your MyFLCourtAccess.com portal account recently?\nAre you using Chrome, Edge, or Firefox as your website browser?\nHave you tried a different browser?\nTry running the browser in incognito mode.\nWhen was the last time you cleared the web browsers cache, cookies and updated?\nHave any new updates been done to your machine that the IT department would need to go in and reset the settings for your web browser to allow pop ups and other information from our website?\nHas your machine been restarted in the last week?\nPlease make sure that the following have been added by your IT Department:"},{"id":"verb-36","title":"Bounce Back Issues","category":"Verbiage Source","status":"Verify before use","text":"There are a couple of reasons for bounce back alerts.\nIt does not mean that your filing was incomplete.\nPlease look over the attached and follow the instructions to:\n1. Clear the alert\n2. Reset the Bounce back counter\n3. Verify the email address is correct with what is in your profile settings vs. the email the e-service was done on."},{"id":"verb-37","title":"Functionability:","category":"Verbiage Source","status":"Verify before use","text":"Please make sure when leaving the website, you use the Sign Out hyperlink in the upper right of the page to \"reset\" for when you sign back in.\nIf you have the site open too long without using it, the site will time out and you will need to \"sign out\" and log back in for function ability to remain consistent."},{"id":"verb-38","title":"Response to issues we are aware of and working on correcting:","category":"Verbiage Source","status":"Verify before use","text":"Thank you for contacting the E-Filing Portal at MyFLCourtAccess.com to let us know of the issue you are experiencing.\nWe are aware of the issue and are currently working to get this resolved as quickly as we can.\nUnfortunately, we do not have a specific time frame for completion.\nYour ticket, with the information you provided, has been sent to the department who are using your examples for testing.\n** the E-Filing Portal is aware of the issue and is currently in the process of being corrected\nYou should make sure to go through each area to make sure none of your information has been removed."},{"id":"verb-39","title":"Deleting the Saved form of payment type:","category":"Verbiage Source","status":"Verify before use","text":"Because payments may still be tied to the form of payment you used previously, it is possible that is the reason you are unable to delete it at this time.\nWhen was the last time the card was used to pay for a submission? Are there any payments till processing from that card or in corrections?"},{"id":"verb-40","title":"Save Button issues on Pasco County filings","category":"Verbiage Source","status":"Verify before use","text":"Pasco has a SAVE button issue in the case party’s area. The filer will need to minimize the zoom on their web browser to 67% to pull the button in enough to be able to click on it to save."},{"id":"verb-41","title":"DIY Filings Questions","category":"Verbiage Source","status":"Verify before use","text":"Thank you for contacting the MyFLCourtAccess.com website Help Desk.\nThe following questions will help me to determine which instructions you may need to use to file.\nAre you trying to use the DIY module with Interview module on the website?\nAre you filing a new case or to an existing?\nIf new- What type of case are you filing for:\nIf this is an existing case, please supply the following information:\nCase#:\nWhat is the name if the document you want to file?\nWhat is the county that you’re filing in?"},{"id":"verb-42","title":"Document #2 is incomplete error","category":"Verbiage Source","status":"Verify before use","text":"There are a few reasons this error typically would happen.\nIf you had the site open too long without activity (15minutes or more), not logging in and out of the website properly, or an issue with uploading.\nUnfortunately, when this happens, you also will need to start the process from the beginning. Do not pull the submission from the workbench."},{"id":"verb-43","title":"Things you need to know before filing a new case:","category":"Verbiage Source","status":"Verify before use","text":"Division filing in\nCase type:\nSub type:\nWhat forms are you going to need to file?\nPlease review / research the information on the clerk of the courts website in the county you are filing in."},{"id":"verb-44","title":"Primary/Alternate email on Portal Account Not Receiving e-Service","category":"Verbiage Source","status":"Verify before use","text":"There are a few things to check.\nCheck the Spam & Junk folders.\nYour email program may not have marked the email addresses the emails are coming from as an “Allowed Sender”.\nYour IT Provider may need to add the email address to the allowed list or whitelist the following IP addresses:\ne-service (eservice@myflcourtaccess.com): 199.127.92.81, 199.127.92.82, 199.127.92.83, 199.127.92.84, 199.127.92.85\nno_reply (noreply@myflcourtaccess.com): 199.127.92.79 and 199.127.92.86\nThere is an issue with your email server and will need to be checked by your IT Provider\nDouble check that you selected persons from the Service list to receive the e-serviced filing."},{"id":"verb-45","title":"“Stuck” and unable to complete filing","category":"Verbiage Source","status":"Verify before use","text":"When you get \"stuck\" like that, it means you must start over.\nMake sure the Petition is the first form you upload in the documents area.\nDo not try to pull the saved submission from the workbench.\nYou will need to make sure not to leave your computer until the filing has been done.\nIf you leave the site open more than 15 minutes, it times out, which could cause issues.\nMake sure when you are done with the website that you are using the Sign Out hyperlink in the\nupper right corner to log out. If not, it could also cause issues with function when you go back into the site."},{"id":"verb-46","title":"Closing a Retired Attorney’s E-portal Account","category":"Verbiage Source","status":"Verify before use","text":"To close the attorney portal account, you must:\nRemove yourself from eservice on all cases. (see attached) Please make sure to check on cases that you are not able to remove yourself from.\nIf a Clerk's or Judge's office added you, please provide us a list with those case numbers and counties they were filed in that you are unable to remove yourself from.\nProvide information on the day retirement is to begin.\nYou must no longer be listed on the Florida Bar as \"Eligible to Practice Law in Florida\".\nThen you can contact us to request closure of an attorney account."},{"id":"verb-47","title":"Uploading issues","category":"Verbiage Source","status":"Verify before use","text":"The entire file name cannot exceed 32 characters including blank spaces\nThe file page size must not exceed 8.5x11\nWhen uploading a file, make sure it is completely uploaded before trying to add another document. (the 100% green bar needs to be gone)\nThe name you have given the file may not be compatible. If your file has special characters you will need to rename the file.\nEx: if it looks like asd_812#.pdf it should be name something else like asd812.pdf\n**Must be in pdf or pdf/a format.\n**No color documents including signatures.\n*Will NOT accept compressed or zipped files.\n*Will NOT accept PDF files if the file name has special or odd characters\n*Will NOT accept PDF files if the file name exceeds 36 characters in length.\n*Will not accept “locked” or “Secured” PDF files."},{"id":"verb-48","title":"Uploaded verbiage/name does not match the document uploaded","category":"Verbiage Source","status":"Verify before use","text":"When this happens, it means there was a function issue.\nUse the below to make sure the right documents with correct description are uploading:\nNormally when we see this issue, we send out the troubleshooting steps below:\nDo not ever use the back/refresh on your web browser.\nDo NOT use the back or refresh buttons\nSign Out using the Sign Out hyperlink, and sign back in."},{"id":"verb-49","title":"When trying to resubmit a filing that was in the Correction Queue- but Payment wont process","category":"Verbiage Source","status":"Verify before use","text":"The payment you made previously has been refunded.\nGo back through the filing, starting with the case information area. Make sure all the drop downs are correct. Scroll to the bottom and click next.\nOn your case parties, click the edit link. On the drop down next to role:\nfor the Plaintiff, check mark both boxes: Primary Party & Filed on Behalf of- make sure all the information is correct, (check that zip code is there) click save.\nFor Defendant, check mark the box: Primary Party make sure all the information is correct, click save.\nScroll down click next. Do the same for each area that comes next.\nIn the documents area, make sure the name of your pdf files do not exceed 32 spaces and contain:\nNO hyphens or underscores, no odd characters (%^&*( )=+) or web dings\nHand key your payment information before scrolling down to click next.\nIf this does not work, please use the following troubleshooting information to relay to you IT Department.\n(Also send them the web browser troubleshooting steps)\nIf still unable to get your payment to process: please email: [internal staff email removed] referencing ticket #"},{"id":"verb-50","title":"Batch Filing Large quantity of filings","category":"Verbiage Source","status":"Verify before use","text":"Per our conversation, to batch file in large quantities:\nhttps://www.myflcourtaccess.com/authority/certified-vendors\nScroll down to the links listed under Batch Filing as a 3rd Party Vendor"},{"id":"verb-51","title":"Microsoft Internet Explorer going obsolete:","category":"Verbiage Source","status":"Verify before use","text":"If you are using a Google Chrome browser, Firefox or Microsoft Edge, you do not need to do anything.\nThe company Microsoft itself is no longer going to support their Internet Explorer browser, so you should not use it for anything.\nThat has nothing to do with our website. This is about Microsoft's IE browser.\n*Emailed information on Internet Explorer no longer being supported by Microsoft\nMicrosoft Link\nhttps://blogs.windows.com/windowsexperience/2022/06/15/internet-explorer-11-has-retired-and-is-officially-out-of-support-what-you-need-to-know/\nPer Standards for Access to Electronic Court Records, Florida law restricts access to some cases, documents, and information based on the record and the user's access level. In addition, not all court progress dockets will have electronic case records available for viewing online. If you are unable to locate or view copies of court documents online, refer to the clerk’s records request page."},{"id":"verb-52","title":"Icons/Symbols- Red Stop Sign- Locked Files","category":"Verbiage Source","status":"Verify before use","text":"We have no jurisdiction over the docket and what filings are locked.\nWe do not have the ability to lock or unlock documents.\nThe documents with the reds top sign that has the white line through it and those that have the locked icons cannot be viewed through the MyFLCourtAccess.com website. To view them, you will need to visit the County’s Clerk of Court website to request access to those files.\nIf you have already requested a View on Demand or a Request for Access and still do not have access, please reach out to the Clerk directly."},{"id":"verb-53","title":"Broward & Miami Dade Cases Summons on Certain Types of Cases","category":"Verbiage Source","status":"Verify before use","text":"If this is a Broward case, you will not be able to upload the summons at this time. You may e-file them after you have been issued a case number.\nIf this is a Miami-Dade County Eviction case, you will not be able to upload the summons at this time. You may e-file them after you have been issued a case number.\nIf this is not an Eviction: (Miami-Dade) and you have been issued a case number:\nType in \"Summ” or “Pre-Trial\" or “Notice to Appear” in the search box in the documents area and click the enter key on your keyboard.\nPick from the options available that suit your filing type.\nIf this is not a Small Claims or Eviction: (Broward)\nType in \"Summ” or “Pre-Trial\" or “Notice to Appear” in the search box in the documents area and click the enter key on your keyboard.\nUnder the Bold Summons for Clerk Issuance area, choose which one suits your needs.\nWhen filing an eviction in Miami\nWhen creating case parties, you also must do it for the physical address of the property as well entering the address in the lines below and click SAVE to add it."},{"id":"verb-54","title":"Adding case party to existing- Miami","category":"Verbiage Source","status":"Verify before use","text":"Miami does not allow the addition to the current party's list to an existing case on the e-filing portal website MyFLCourtAccess.com.\nI would advise to go ahead and file your paperwork, choosing an attorney or other party from the Current Parties list to be able to get your paperwork filed to the case."},{"id":"verb-55","title":"Watermarked Copies","category":"Verbiage Source","status":"Verify before use","text":"If you are the Attorney of Record and you filed through the website. MyFLCourtAccess.com eportal, you should be able to access the filing from the docket.\nIf the Clerk does not have you listed on the docket header as the Attorney of Record with a bar number, you will not be able to access through the portal and it is suggested that you to go to the Clerk's website to see if you can access or request an unwatermarked copy via their website.\nThe e-filing portal does not watermark documents, nor have the ability to remove them.\nThis is a clerk action, not a portal action.\nThe portal does NOT upload your documents to the docket.\nThe e-filing portal functions as the electronic messenger that sends your files to the clerk. The clerk then takes your files, runs it through their software, locks, marks and uploads the file to the docket.\nPlease contact the clerk for a clean copy as we cannot assist with this issue."},{"id":"verb-56","title":"When case party's names do not show up it is for 1 of the following reasons:","category":"Verbiage Source","status":"Verify before use","text":"1. When 1st filed to the case, the case party information was not correctly saved. I will list that information below.\n2. If this is a domestic violence case, names will not be displayed.\n3. If this is sealed or confidential, names will not be displayed.\n4. You did not file to this case under your attorney's account through the MyFLCourtAccess.com website.\n5. You did file, but the clerk has not accepted and docketed the filing.\nFile your documents and submit them to the Clerk. Once the Clerk has accepted the documents, the case information will now reflect correctly in your My Cases list."},{"id":"verb-57","title":"Unable to Load Webpage/Timing Out","category":"Verbiage Source","status":"Verify before use","text":"Is it 1 computer in the office or all of them?\nIs anyone outside of the office having the same issue?\nHave the Cache & Cookies been cleared?\nHas the browser been updated?\nIs your pop-up blocker turned off?\nIs your browser allowing redirects from our site?\nWhen is the last time you updated/restarted your computer?\nHave you tried to access from a different browser?\nIf all the above has not helped, please contact your IT Department and/or your internet provider with your issue.\nI would also request them to check your internet speed."},{"id":"verb-58","title":"How do I get a PDF out of XFA format?","category":"Verbiage Source","status":"Verify before use","text":"How do I convert an XFA to PDF? To convert XFA PDF to normal PDF, click the Print button, on the Print window that opens, tick Print as Image, and click Print. The XFA form will be converted to a PDF file that you can open with any PDF reader."},{"id":"verb-59","title":"Origin Key Errors:","category":"Verbiage Source","status":"Verify before use","text":"Have them change the browser they are using.\nMake sure to use the Sign Out hyperlink to log out of the website.\nIf the above doesn’t work, have them hit the F12 key to bring up information under the Console tab and grab that sequencing to send to Analyst team."},{"id":"verb-60","title":"Looking up the EPTL# in the Organization account (For the Admin of the account)","category":"Verbiage Source","status":"Verify before use","text":"Please contact the organization administrator on the firm account to get that information since they have access to it.\nI have the administrator as:\nThe EPTL# is the same as the financial ID. All you need to do is log in, go to My submissions, enter the EPTL# into the financial ID box, change the submission date to a week before the charge was made and hit search.\nIt will list all the information for the filing."},{"id":"verb-61","title":"Paying fees on DOH-DOA cases that had not Trial court assigned previously","category":"Verbiage Source","status":"Verify before use","text":"This source heading contains no standalone text in the supplied document."},{"id":"verb-62","title":"Self Rep/Attorney needs to update address/email/phone information","category":"Verbiage Source","status":"Verify before use","text":"I am not sure exactly where you need to update your address.\nIs it with the Clerk of the Court?\nDo you have an e-portal account for the website MyFLCourtAccess.com? Is that what you need to update?\nIf so, you can log in, go to your profile under the My Account dropdown, change the information and scroll to the bottom and click update.\nHowever, this will NOT update your information on your case or with the Clerk's office.\nDo you have a log in with the Clerk of the Court website? If so, go onto their website and update your information as well.\nContact the Clerk of the Courts office to see if you need to file to your case the designated email/address form to update your information.\nIf that is what is needed, you can file it with the below instructions:\n(Paste How to- File to Existing case here)"},{"id":"verb-63","title":"When the Case number / Division or County changes:","category":"Verbiage Source","status":"Verify before use","text":"If there has been a change in the County or division of a case, there are a few things you will need to do:\nDivision / Transferred Changes:\nDo NOT pull the case from your My Cases to file to it. The portal will not auto update your case number/information.\nAccess the NEW case# via the E-filing map. When you submit a filing to the Clerk this way, once the filing is accepted it will populate with the correct division/ case# for you to file to the case correctly in the future.\nYou may need to add yourself back to the E-service list during the filing if you want to receive eService\n**You will need to refile to the NEW case# to get access to the docket through the portal again.\nCounty Changes:\nDouble check your case number with the new county the case is being transferred to. The case number will be different.\nDo NOT pull the case from your My Cases to file to it. The portal will not auto update your case number/information.\nAccess the NEW case# via the E-filing map. Once you submit a new filing to the Clerk via the portal, and the filing is accepted, the case will populate with the correct County for you to file to it correctly in the future.\nI would suggest filing a Notice of Appearance or designation of email/address form to the new case.\nAsk the Clerk where to find the form(s) as we do not offer them on the website.\nYou may need to add yourself to the E-service list to the transferred case during the filing.\n**You will need to refile to the NEW case# to get access to the docket through the portal again."},{"id":"verb-64","title":"Requests for Refunds- from the Portal","category":"Verbiage Source","status":"Verify before use","text":"I will need more information to send over to banking to initiate a refund.\nWhat is the date of the charge listed on your statement?\nHow much was the charge?\nWhat is the filing number the overpayment derived from?\nIs this a credit, debit or ACH account?\nWhat are the last 4 numbers of the account?"},{"id":"verb-65","title":"Requests for Refunds- from The Clerk of the Courts","category":"Verbiage Source","status":"Verify before use","text":"You will need to contact the Clerk of the Courts on the County you filed in and speak to the division your case is filed in. ie: Domestic Relations/Family, Probate, County or Circuit Civil….etc.\nSince they accepted the filing and pulled the funds, they would need to refund you.\nIf they tell you to call the e-filing portal, we cannot issue refunds. Ask them to request it from the portal if necessary. (There is a formal way most counties must use when contacting us to request refunds) We cannot issue just by your request alone.\nPlease be advised, the E-Filing portal website; MyFLCourtAccess.com website is not the Clerk of the Court, Judge’s office, or the District Court of Appeals."},{"id":"verb-66","title":"When a filing gets accepted, but the fee was not paid","category":"Verbiage Source","status":"Verify before use","text":"When the clerk has accepted the filing without the fee, there are\n2 options to make the payment:\nCall the Clerk for the court you filed in and ask how they want you to provide payment.\n(Phone or US Mail)\nRefile the form(s) and pay the fee, losing the time/date stamp of the original.\nJust Verbiage to use later on:\nPreliminary root cause: The issue occurred due to a processing bottleneck within “…...\nWe are still investigating the cause of this issue and will provide further information in the published Post-Incident Report for this event.\nNext steps: -We are working to identify and analyze the cause of this event to confirm any additional required actions to better detect, prevent, and recover from similar occurrences of impact."},{"id":"verb-67","title":"Summonses- -The process of Filing and Serving","category":"Verbiage Source","status":"Verify before use","text":"Filing and serving a summons differs by:\n1. The county\n2. The type of case\nIt is your responsibility to find, file, and serve the summons.\nPlease visit the website for the Clerk of the Court in the county you are filing in, to see what information they have on their Summons procedure.\nExample, if your case is an eviction case in Miami-Dade, you cannot file the summons online and must do it in person or by mail.\nOnce the Clerk receives, and time/dates the summons, you will need a copy of the stamped summons and then determine how you will serve the summons.\nCheck the Clerk website.\nFor most counties, you can find the summons form on the Clerk website. (they may have you look somewhere else, if you have a case#, you will file to the existing case)\nFill it out and upload to your existing case paying the $10 fee for the Clerk to stamp the summons. (do not click submit unless you see the $10 fee)\nHow the Clerk gets you the stamped copy is for you to inquire from the Clerk.\nOnce you have the stamped copy, you can have the Sheriff's Department or Process Server serve it. You will need to contact them for their procedure as well, on how they get it from you, who and where to pay.\nOnce the summons is served, how do you get the notification it was served so you can upload it into the case file? (return of service of summons served)\nIs it your responsibility or the agency serving the summons responsibility to upload it to the case?\nThese are questions you should ask the agency you choose to use.\nThere is a difference between eService and Service of a summons document.\neService done on the e-filing website, is only to be used to notify another party that you are filing paperwork to the case.\nIt is NOT a replacement, nor does it serve as a Summons that gets served on the other party to appear in court.\neService is a courtesy, not a law, unless on the filing it specifies that a copy was sent via eService through the filing portal.\nDepending on the county, it is the filers responsibility to file the summons, get a copy of the stamped summons from the clerk and serve it upon\nthe other party by sheriff or a process server. You will need to check the Clerk of the Court’s website for the county the case is filed in to verify.\nIt is the responsibility of all parties to read the rules and procedures of such for their case type on the clerk of the courts website to know what is required of them.\nIf the information is not available on their website, please call them to get direction on where you can find that information.\nThe MyFLCourtAccess.com website is only used to file to create new cases or file to existing cases.\nWe are not the Clerk of the Courts."},{"id":"verb-68","title":"When documents change while viewing / correcting in the documents area","category":"Verbiage Source","status":"Verify before use","text":"This can sometimes happen for a couple of reasons.\n1. Your web browser needs to have the cache and cookies cleared and the browser updated.\n2. You did not sign out of the website using the Sign Out hyperlink but just X out of the web page, which can cause function issues when you log back in\nover an already \"open\" session.\n3. The website was open too long causing it to time out. Usually, if you have the website open and idle for more than 15-20 minutes.\n4. Not going through the process of choosing a document type before uploading the new document to replace the one during a filing in the correction queue.\nIf the above happens while fixing a filing in the correction queue to an existing case:\nPlease go to the docket, open the documents to see what has been filed, then upload documents that were not uploaded in another filing to the\nexisting case.\nParty Names from the Financial ID#\nYou can look this up by going to My Submissions.\nEnter the EPTL number from your statement: 4229336 into the Financial ID box.\nChange the Submission date to a week before the money was removed from your account.\nYou can go back 90 days from todays date.\nClick search.\nIt should bring up the filing for you to click on and see the case party names."},{"id":"verb-69","title":"Paying for & Filing Bonds","category":"Verbiage Source","status":"Verify before use","text":"This must be done in person at the courthouse and cannot be filed & paid for on the eportal."},{"id":"verb-70","title":"Filings “stuck” in Pending, Transmitted, Validating, Send to Local","category":"Verbiage Source","status":"Verify before use","text":"Thank you for contacting the E-Filing Portal.\nI have turned this over to the analyst department.\nAs soon as resolution has been determined, I will contact you."},{"id":"verb-71","title":"5-day vs 20-day summons on Miami Evictions: doc type not available","category":"Verbiage Source","status":"Verify before use","text":"The difference is the case type chosen from the drop down.\nInstead of choosing Evictions on the filing you chose County Civil.\nSo the 5-day will not be available for that one, only the 20-Day\nType: County Civil - $8,001 To $50,000 / Condominium (Claims $8,001 - $15,000) only 20 day\nType: Evictions / Residential (Claims $15,001 - $30,000) 5 day available"},{"id":"verb-72","title":"Organization Portal Administrator Videos","category":"Verbiage Source","status":"Verify before use","text":"Benefits of creating an organization\nhttps://www.youtube.com/watch?v=FZt6ef3J8a8\nBeing A Portal Organization Administrator\nhttps://www.youtube.com/watch?v=C8Y_v8Qw-iU\nAdministrator must be an attorney and possess a FL Bar#\nYour Administrator will need to have your log in and password.\nAbility to Manage Users:\nYou can add your new attorneys to your organization.\nIf they have a portal account, you can use the \"add unaffiliated user\" to pull them in under the organization.\n(As long as the account was not tied to a state agency ie: Public Defender's office, Attorney General's office, etc.)\nYou may want to check to see if their account needs to be disassociated from a previous firm organization.\nYou can also delete them from the organization, so they no longer have access to the Firm's information.\nThe \"key\" allows you to reset passwords.\nPlease remember, unless you are a county or state agency, the account belongs to the Attorney. It is theirs to take with them when they leave the firm.\nOnce they leave the firm, you are not authorized to make changes to, file on their account or prevent them from using it.\nPlease disassociate all users who leave the firm, untying them from the organization account.\nFor an attorney who leaves the firm, please change their password to a temporary password and give it to them upon leaving.\nUnder “Filing Options”: you will see Organization Submissions\nThis will allow you to pull up submissions made by everyone in the organization.\nUse the FILER drop down to choose a specific attorney's filings you want to view.\nThe Submission Date From: only goes back 90 days\nAnother benefit: My Fees\nYou can look at the organization, or by an individual.\nAgain, you can only look back over the last 90 days of what has been filed/charge.\nYou can only view documents eServiced for 14 days.\nInformation can be exported to an Excel spreadsheet.\nYou can see the account the charges were made on and the amounts.\nIf you click on the Filing number, you can pull up case information such as case#, Case parties, Matter# if there is one, and who it was filed under.\nYou can see the description of the documents submitted but cannot open any files from this page.\nThis is also where you can see the breakdown of fees with stage of processing and the order#."},{"id":"verb-73","title":"How to add an attorney to an organization account","category":"Verbiage Source","status":"Verify before use","text":"Please check with the firms portal administrator, who is someone in the firm or organization first.\nThey have the ability to add you."},{"id":"verb-74","title":"Changing Organizations","category":"Verbiage Source","status":"Verify before use","text":"If a user’s account already exists and their account is associated to a specific organization, that user can send in a request to be removed from the organization.\nWhen the user goes to a firm or agency that has an organization already established, after they have been removed from the previous organization the Administrator for the current organization can add them from their E-Filing portal account."},{"id":"verb-75","title":"Request to customize an account for accounting department needs:","category":"Verbiage Source","status":"Verify before use","text":"This source heading contains no standalone text in the supplied document."},{"id":"verb-76","title":"Delivery / copy of filings","category":"Verbiage Source","status":"Verify before use","text":"We do not \"customize\" accounts for any reason.\nIn reference to multiple filings, and a central depository for your team to access \"receipts\" from those filings, I suggest having your attorneys add an email address (specifically for your accounting needs) to their user profile (on each attorney portal account) as the alt 1 or alt 2 email address.\nIf they utilize all 3 (you cannot add any more) they will need to add you (and check the box next to the name) onto the service list when they file & submit to a case.\nIn addition to this, if the email addresses the eservice notices comes from has not been added to your allowed/permitted list in your email program, you could miss them and they may in up in Junk/Spam or stuck in one of your filtering software programs.\nWe recommend that you contact your IT group and ask them to whitelist the following email addresses/IP addresses:\nAnd that everyone set up with an email program add them to their allowed senders listing.\ne-service (eservice@myflcourtaccess.com): 199.127.92.81, 199.127.92.82, 199.127.92.83, 199.127.92.84, 199.127.92.85\nno_reply (noreply@myflcourtaccess.com): 199.127.92.79 and 199.127.92.86\nIf you miss an email, an alternative method to finding an eservice email withing the past 90 days is to use the Email Log.\nYou can access the Email Log from your Portal account\n(under My Account>Email Log use dropdown Eservice) to determine if those filings you've not received service on, were delivered to the email addresses listed on the Primary account.\nIf the Primary account received the email, but the others listed on the account as the alt 1 & 2 email did not, it is an issue with their email program and the allowance settings on it."},{"id":"verb-77","title":"Adding additional Parties to an already filed case","category":"Verbiage Source","status":"Verify before use","text":"If while in the Portal and you do not see the Add Party (see below)\nYou can do 1 of 2 things:\nCall the clerk of the courts to see if they will allow additional parties to be added via the eportal.\nChoose any party listed to file on Behalf of and file without adding the party/parties and the clerk should add them to the list & case."},{"id":"verb-78","title":"Notes: How to create a Master Ticket","category":"Verbiage Source","status":"Verify before use","text":"new ticket,\ncreate under team person name\nmaster in the summary add date to summary\nfiler role would be other\nsource: on site\nurgency & impact set to high\ncheck mark Master box\nsave\nOnce it has been resolved, also click the Resolved Down box by the resolution\nelow is the list of filing statuses:\nFilings\n0- Not Known\n1- Received\n2- Validating Filing\n3- Pending Review\n4- Being Reviewed\n5- Ready for Filing\n6- Sending to Local System\n7- Pending Filing\n8- Error Retrieving Status\n9- Correction Queue (formerly the Pending Queue)\n10- Filed for Judicial Review\n100- Filed\n101- Partially Filed\nRecordings\n200- Recorded\n201- Partially Recorded\n1000- Errors\n1001- Rejected\n9998- Received Queue\n9999- Ready for Filing Queue"},{"id":"verb-79","title":"No Submit button or Submit button grayed out.","category":"Verbiage Source","status":"Verify before use","text":"Confidential / Sealed Filings\nI cannot answer your questions on how to file to a confidential or under a sealed case.\nSince we are not the Clerk of the Courts, I would suggest the following:\n1. Visit the Clerk of Court’s website or call them first to see if they have any rules & procedures you may need to adhere to when filing a/to a confidential or sealed case.\n2. If you’re filing via the portal, you will need to know which form to use to note that your filing is confidential.\nNotice of Confidential Information within Court Filing\nOR\nMotion to Determine Confidentiality of Court Records\n3. Does the clerk require that form to be the 1st page of the pdf document you are filing with the following pages of the document listed after it in the same pdf?\n*Note: Does the clerk require the form to be attached to the front of the documents you are filing in the same PDF, or does the form need to be in its own pdf and uploaded separately as the first pdf in the filing session or not?\n4. If the options are shown, make sure to select one of the 3 options under the documents upload to label your type of confidential information.\n5. Do not select anyone for e-service at the time of filing so the clerk can redact information before going to the docket."},{"id":"verb-80","title":"Please verify the confidential rules & regulations with your Clerk of the Courts office.","category":"Verbiage Source","status":"Verify before use","text":"This source heading contains no standalone text in the supplied document."},{"id":"verb-81","title":"How docket and its filings access and eService works.","category":"Verbiage Source","status":"Verify before use","text":"Access-\nYou can only access the case and its documents through the e-filing portal MyFLCourtAccess.com if ALL of the below applies:\n1. You are the attorney of record listed on the header of the docket.\n2. AND-You have filed to this case through your attorney e-filing portal account as the Attorney of Record.\n3. If the case is not disposed, closed or sealed or confidential.\n4. If the case is not a Probate/Formal Probate case.\n5. If the page count of the filing document you are trying to access is under 15-20 pages."},{"id":"verb-82","title":"How do I find a receipt for filing fees done in the last 90 days?","category":"Verbiage Source","status":"Verify before use","text":"Under the My Account>Email Log.\nChange the date information to when the filing was done.\nThen use the drop down for type of email: Processing Completed.\nIt should match your filing number\nOr\nUnder the Filing Options>My Fees\nChange the date information to when the filing was done.\nEnter the filing number in the Submission# box.\nClick on the Search button.\nIf All of the above does not apply, you will need to visit the Clerk of the Court's website for the county filed in.\nHello, and thank you for contacting the E-Filing Portal website MyFLCourtAccess.com Help Desk.\nNot all cases have the option for certified copies.\nIf the option is available, the below information should be listed on the case.\nThe clerk will need a formal letter requesting the document #(s) with:\nThe document number and description from the docket.\nThe case number listed on your request.\nYou may need to specify which format, or call them to see what format those copies are available in.\nI am not sure if your request is for copies that are to be delivered by email or in paper form.\nYou will need to speak to the clerk on what the options are, and if in paper form, if there will be an additional charge for the post office.\nOn the Case Information area- you should input the # of documents on the 1 line, and the total number of pages for those documents on the 2nd line.\nWhen you get to the upload page:\nYou can use any of these document types to upload to.\nOther\nLetter\nSubsequent"},{"id":"verb-83","title":"Writ of Ex Parte-","category":"Verbiage Source","status":"Verify before use","text":"Is filed for Involuntary Examination and can be filed by anyone who has observed the behavior and can describe the actions of a person that cause them to think the person has a mental illness and requires a mental health exam.\nDivision: Probate\nCase Type: Mental Health\nSub Type: (choose 1) we cannot tell you which to choose."},{"id":"verb-84","title":"Law Enforcement- ability to receive/download","category":"Verbiage Source","status":"Verify before use","text":"If they already have an account, update the Security Role to as shown below."},{"id":"verb-85","title":"Form/Filing is accepted but the fee was not paid (Summons & other Fees)","category":"Verbiage Source","status":"Verify before use","text":"When the clerk has accepted the filing without the fee.\nYou have 2 options to make the payment:\nCall the Clerk and ask how they want you to provide payment.\n(Phone or US Mail)\nOr refile the form and pay the fee. (you will lose the date/time stamp)"},{"id":"verb-86","title":"Filed On Behalf of:","category":"Verbiage Source","status":"Verify before use","text":"This will pop up for 1 of 2 reasons and in 2 different places.\n1st: If this is a new case filing, it will be in the setting up of the case parties."},{"id":"verb-87","title":"On the Case Parties/Roles set up:","category":"Verbiage Source","status":"Verify before use","text":"Do NOT use ANY punctuation when entering information\nIf you input a business/organization name, you can only input up to 50 characters.\nThis includes empty spaces.\nFor the role of Plaintiff/Petitioner:\nAlways check the boxes to the right Primary Party & Filed on Behalf of\nFor the role of Defendant/Respondent: Only check the box Primary Party\nYou do not check any boxes for Attorney (if one is listed & filing)\nIf applicable:\nFor the role of Decedent: Only check mark the box Primary Party\nYOU MUST CLICK “SAVE” AT THE BOTTOM RIGHT OF THE SCREEN\n2nd: If this is an existing case, you will need to follow the instructions on the case party’s area.\nYou will need to click on the party to highlight them, once highlighted, scroll down and click on the NEXT button."},{"id":"verb-88","title":"Where fees populate / appear:","category":"Verbiage Source","status":"Verify before use","text":"There are only 2 places on the portal website where fees pull from.\nThe Case Information Tab\nOR\nThe Documents uploading area (after the document has been uploaded)\nThe below uses a summons as an example.\nIf the fee populates in 1 area, the fee for the same thing should not populate from the other. If the fee does not populate in either, do not file and please contact us.\nFrom the Documents tab:"},{"id":"verb-89","title":"Subscribe - Unsubscribed definitions/explanation","category":"Verbiage Source","status":"Verify before use","text":"We have 2 types of \"subscribe\".\nA case subscription\nIs when you add a case from under your portal profile area (only pertains to certain types of cases), and you can go in and remove at any time on your own.\nYou have (subscribed) connected yourself to the case to be notified of filings (ONLY pertains to filings done through MyFLCourtAccess.com website)\nthrough the eportal. You do not get a copy of what was filed. This is only a notification that something has been filed to the case.\n2. Unsubscribe from an e-service list.\nIs when someone has added you to the service list of a case to be notified when filings are made into that case.\nIf you received an eService email, and clicked on the remove link, which has pulled your name and email from the service list of this case.\nYou should no longer get eservice emails unless someone goes back in during a filing and adds you.\nAP Cases- no Summons option as of 5/1/2024\nCurrently, the appeals section is not set up to process financial transactions. If the filer wants to use subsequent circuit civil this should allow for the summons to be selected and paid for. Or they can just efile the document under the appeal filing and contact the clerk for payment and issuance."},{"id":"verb-90","title":"This is what emails look like from a case subscription","category":"Verbiage Source","status":"Verify before use","text":"This source heading contains no standalone text in the supplied document. The original section appears to rely on an embedded screenshot, which is intentionally excluded from the GitHub Pages edition."},{"id":"verb-91","title":"Indigent Application","category":"Verbiage Source","status":"Verify before use","text":"In the beginning of a lawsuit, when you file the indigent application on the 1st submission (this is uploaded in the fees & payments area), you do not need to pay a fee.\nHowever, if the Court denies your application, you will need to pay all of the filing fees before they process to create a case and issue a case number.\nPlease visit the Clerk of the Courts website for the application."},{"id":"verb-92","title":"Bookmarks being stripped from Index Filings","category":"Verbiage Source","status":"Verify before use","text":"[2:10 PM] Corey Redig\nResolved this (new submission Filing # 201393898), customer had to convert doc to pdf/a 2-b but the bookmarks now appear on their submitted document\n[2:11 PM] Deborah Moss\nCorey Redig you want to explain a bit for me? So does that mean those who have a similar issue, tell them it needs to be pdf/a 2-b?\n[2:12 PM] Deborah Moss\nIs this why the bookmarks are being stripped?\n[2:19 PM] Corey Redig\nPretty sure this works for anyone with complaints about missing bookmarks in appendices or lost data from index tables (I've no idea why it works, or why standard pdfs don't). I had him do the conversion at pdf2go.com, idk of another way to do it that would be the same for everyone's computer/os\nWe do occasionally see this issue. The solution we have been able to pass on that works is the following:\nFiles will need to be converted from doc to pdf/a 2-b so that the bookmarks will appear on the submitted documents.\nYou may be able to do this on the website: pdf2go.com\nReferred to pdf2go.com to convert using the pdf/a 2-b instructions."},{"id":"verb-93","title":"Transcribing tickets:","category":"Verbiage Source","status":"Verify before use","text":"When you are transcribing tickets and it is a county employee- please go to the More link, click on Org Unit\nClick the county they are from.\nClick on the Employee tab and search their name. If you do not see them, let me know and I will add them."},{"id":"verb-94","title":"Purchasing Electronic or Certified copies of filings","category":"Verbiage Source","status":"Verify before use","text":"This source heading contains no standalone text in the supplied document."},{"id":"verb-95","title":"Broward","category":"Verbiage Source","status":"Verify before use","text":"Unfortunately, not all electronic documents are available for purchase online via the Electronic Certified Document service for various reasons.\nFor further assistance, please refer to the information provided below. If you have any questions, contact the Public Access Help Desk @ (954) 831-5588, or send a follow-up email.\nIf the electronic document in question is available for viewing online, but is not available for purchase via the Electronic Certified Document service, please note, the following alternative options below on how to obtain an official copy of the electronic document:\n• Go in-person to purchase the document from the Archives division, or from the division in which the case is filed, or\n• Submit a Request for Court Records which will be processed in 1-2 weeks by the Archives Division.\nThe cost varies per page and an additional cost for certification if requested.\nIf you have any additional questions, feel free to contact the Public Access Help Desk @ (954) 831-5588.\nCase # \"99-9999\" is a special case # used by CTrack (case maintenance system for District Courts of Appeal and Florida Supreme Court) for cases filed via \"Case Number Pending \" filing path. Case # Pending filings are docketed in C-Track using \"99-9999\" for case #.\nFiling a Complaint for Qui Tam Action- Done as a Circuit Civil\nOther Circuit Civil and then"},{"id":"verb-96","title":"Zoom information, request or to appear telephonically","category":"Verbiage Source","status":"Verify before use","text":"Thank you for contacting the E-Filing Portal website MyFLCourtAccess.com.\nUnfortunately, I am only able to assist you with guidance to upload your request form.\nTo obtain the form, please visit the website for or call the Clerk of the Courts in the county your case is filed in.\nThe E-filing Portal help desk only provides navigation and technical support instructions on how to navigate the website to submit/upload documents to create a case, or to an existing case.\nPlease be advised that the E-Filing portal website MyFLCourtAccess.com is not the Clerk of the Court or the District Court of Appeals.\n**We cannot verify your court date.\nWe cannot help you access Zoom, telephonically connect, or reschedule your Zoom meeting.\nWe do not offer or have access to forms to send to you."},{"id":"verb-97","title":"Court Monitor- registrations","category":"Verbiage Source","status":"Verify before use","text":"How do you verify a license#:\nhttps://www.myfloridalicense.com/wl11.asp?mode=0&SID="},{"id":"verb-98","title":"E-filing portal accounts","category":"Verbiage Source","status":"Verify before use","text":"Are supposed to be set up for the individual attorney.\nSay you have 10 attorneys in your office.\nEach of them is to have their own e-filing portal account, set up under their own name and email address.\nThose 10 attorneys are not supposed to file under another attorney's account.\nEach account has an individual username and password that are specific to that attorney.\nThis is for historical purposes so that attorney can log into their account to see when they filed and to what case.\nThe e-filing portal account belongs to that attorney, not the firm. So, when the attorney leaves the firm, the attorney takes\nthe account (changing the password, address, email) to their updated information.\nWhen an attorney leaves the firm, it is their responsibility to remove themselves from the eservice list\nof cases they filed to using the email address from the firm they are leaving.\nOnce they leave the firm, if another attorney is taking over, the attorney needs to file a Notice of Appearance via their portal account,\nand select themselves for service at the time of filing (because adding you to eService is not automatic)."},{"id":"verb-99","title":"How to remove / change cases status from My Cases","category":"Verbiage Source","status":"Verify before use","text":"If you would like to edit the entries so that they do not appear, click on the case’s “Court Case #” in your “My Cases”.\nYou will be taken to a window showing the case’s Service list, across the top of the screen, beneath the Save button, there will be 4 tabs to select from.\nClick on “My Status for this Case”, mark the bubble next to “This is not an active Case. Do not Show on MY Cases List.”, then click Save.\nMoving forward, when you go to your My Cases, the default setting will be to only search Active cases, so those that you’ve updated to “inactive” will no longer be shown. If you ever need to look at the inactive cases again, you may update the search to include or only show the Inactive cases."},{"id":"verb-100","title":"Exceeds the 8.5x11 page size requirements (resize)","category":"Verbiage Source","status":"Verify before use","text":"Depending on how you converted your pdf file, some printers and scanners used or the software program you are using to create the pdf, is not converting the document correctly.\nWhen physically scanning, or printing pages out and then scanning:\nMost machines have rollers (some plastic, some rubber). If they are worn down or need to be cleaned, they could be skewing the page when it pulls it through the machine. Then it throws it off the size you were scanning it to be.\nEspecially when the pages have been previously stapled or creased.\nOr-\nIn the software or the setting on the machine itself:\nYou may need to review and or adjust the settings to the correct size.\nThere are a few websites that assist with the resizing / conversion of files.\nIf you would like to use it, see the attached flyer with instructions provided.\n(note to HD person-attach the instructions to the email)\n** Emailed the instructions on resizing documents for submission"},{"id":"verb-101","title":"Notice of Related cases Form","category":"Verbiage Source","status":"Verify before use","text":"Even if there are no related cases, you still need to fill out the form and file it. Fill it out to the best of your ability. No other related cases? You can just mark N/A if it does not apply."},{"id":"verb-102","title":"When asked about ADA Compliance:","category":"Verbiage Source","status":"Verify before use","text":"We can provide you with written instructions on how to file, but we are unable to tell you what forms are needed and where to find them as the e-filing portal does not get into the procedural side of filing.\n1. By law, MyFLCourtAccess.com employees are not allowed to file on behalf of the filer.\nWe are happy to provide documentation on how to file documentation.\n2. You, the filer, should contact the clerk's office where your case is filed as we cannot demand the clerk provide you direct access.\n3. As a SRL (self-represented litigant) you are currently not required to use the Portal to submit to the county and can do so in person.\n4. You can contact your local Legal Aid office which, based upon your disability and financial situation, they may be able take you on as a pro bono case.\nIf this is a Civil case, another option is the Florida’s Relay Service 941-741-4022"},{"id":"verb-103","title":"Unable to add a case party when filing to an existing case","category":"Verbiage Source","status":"Verify before use","text":"If the county does not have the Add Party link available, or the dropdown for the party type, it is possible they will not allow for any new additional case parties to be added via the Portal.\nPlease choose from either the attorney listed or any other party listed, so that you can get your submission to the clerk.\nIt does not matter which person you select as the clerk does not collect that information.\nIf the clerk is going to allow the party to be added to the case, they will insert the party details to the docket.\nWhen escalating a ticket to the Analyst Team (per Gia-teams (3/12/2025)\nThe analysts are tier II support for support specialists. If there is an issue that you all need an analyst to review and assist with, a task should be created. The analyst should then review and if they cannot resolve the issue or have to provide a workaround, the analyst should post in the Service Desk channel. That said, if it is something simple like refund a payment without a filing #, the support specialists can post without having to seek guidance from an analyst. Make sense?"},{"id":"verb-104","title":"Exemption from e-service:","category":"Verbiage Source","status":"Verify before use","text":"If you need an exemption, review the instructions for these forms and the relevant Florida Rule of General Practice and Judicial Administration 2.516 Section B, sub section: (D), (i), (ii) to understand the procedures for doing so. See (D), (i), (ii) starts on page 168\nhttps://www.flcourts.gov/content/download/217909/file/Florida-Rules-of-Judicial-Administration.pdf\nPlease contact the Clerk of the Courts for the form needed to file for exemption."},{"id":"verb-105","title":"PDF Validation / Identifier","category":"Verbiage Source","status":"Verify before use","text":"I ran the document through a pdf a validator to see what it returned with. See below.\nAttached is what I converted to PDF/A but it gave me an error that certain components couldn’t convert.\nThat being said I was able to run the converted doc through the validation, and it passed the PDF/A check.\nYou can use the online tool to validate your file and refile the document.\nEither way that original PDF was not in PDF/A format.\nhttps://www.pdfen.com/pdf-a-validator"},{"id":"verb-106","title":"PDF file has corrupt. deleted, missing, or stacked verbiage","category":"Verbiage Source","status":"Verify before use","text":"When you come across tickets where the filer is reporting their submitted PDF document had stuff deleted from it, letters turn into wingdings, letters stacked on top of one another it most likely is they are using a font that isn't standard. To test this, you will need to have them send you the original document and run it through the TEST Portal to see if the results are the same. If they are, you can post in Teams, provide the original document and tag Rao.\nRecommendations for the filer (include the PDF/A FAQ document and the link to the video): https://www.youtube.com/watch?v=vwx288WZGaU\nMake sure you are using a reputable PDF creator\nUse one of the standard fonts: - Times Roman - Times Italic - Times Bold - Times Bold Italic - Courier Regular - Courier Oblique - Courier Bold - Courier Bold Oblique - Helvetica Regular - Helvetica Oblique - Helvetica Bold - Helvetica Bold Oblique - Symbol - ITC Zapf Dingbats"},{"id":"verb-107","title":"Broward Court Divisions","category":"Verbiage Source","status":"Verify before use","text":"CACE- Circuit Civil COCE- County Civil Central (this could be a SC or CC case) COWE- County Civil West Satellite Courthouse (this could be a SC or CC case) COSO- County Civil South Satellite Courthouse (this could be a SC or CC case) CONO- County Civil North Satellite Courthouse (this could be a SC or CC case)"},{"id":"verb-108","title":"Miami","category":"Verbiage Source","status":"Verify before use","text":"This source heading contains no standalone text in the supplied document. The original section appears to rely on an embedded screenshot, which is intentionally excluded from the GitHub Pages edition."},{"id":"verb-109","title":"Status of Filing","category":"Verbiage Source","status":"Verify before use","text":"Log into your account. In the upper right, click on My Submission:"},{"id":"verb-110","title":"Character lengths for inputting information:","category":"Verbiage Source","status":"Verify before use","text":"50: for business or organization (this includes blank spaces)\n30: for first names (this includes blank spaces)\n30: for middle names (this includes blank spaces)\n30: for last names (this includes blank spaces)\nIf it exceeds the above, please contact the clerk of the court for an alternative."},{"id":"verb-111","title":"Endpoint errors:","category":"Verbiage Source","status":"Verify before use","text":"endpoint error means the county's endpoint is down/unreachable- this is a county problem not a portal issue."},{"id":"verb-112","title":"Unable to click on and preview the file they just uploaded:","category":"Verbiage Source","status":"Verify before use","text":"May have had an update to their adobe or their web browser.\nHow to fix:\nGo to your web browser setting- manage extensions- adobe and uncheck the (auto open)\nthen can preview the uploaded file the documents section."},{"id":"verb-113","title":"OCRS viewing/ VOR VOD issues","category":"Verbiage Source","status":"Verify before use","text":"Thank you for contacting the E-Filing Portal website MyFLCourtAccess.com Help Desk.\nThe OCRS website is \"powered\" by Civitek, however, Civitek is not the entity that processes the VOD requests and does not have access to documents or the ability to send them to you or advise how to access or download.\nThere are a couple of things you may want to look at:\n1. The web browser you are using, you may need to set the website up to allow for popups and redirects.\n2. If the file is too large, it may take a while to pull or not pull at all.\nUnfortunately, this is not something Civitek can control or correct.\nPlease contact the Clerk of the Court in the county the case is filed in for more information.\n3. If the case is a Dissolution, Probate, or confidential case, those are not accessible from the OCRS and you will need to contact the Clerk's office for instructions."},{"id":"verb-114","title":"Proposed Order word doc issues","category":"Verbiage Source","status":"Verify before use","text":"When the cover letter is getting through to the JA, but the word doc is not;\nReceived a message about personal information settings when trying to open the file in MS Word. ICMS was unable to process the order. After clicking 'Change setting' and re-uploading the file to ICMS, it worked. Ask the filer to remove the personal information setting and resubmit the file?"},{"id":"verb-115","title":"Test card numbers for the Adyen paymen t processing","category":"Verbiage Source","status":"Verify before use","text":"Test card numbers | Adyen Docs\nACH\n\"routing Number\": \"061103852\", \"account Number\": \"123978027"},{"id":"verb-116","title":"Filing has the number 1 in weird places","category":"Verbiage Source","status":"Verify before use","text":"Wavey Bates at Scott Tankel- the weird 1 being inserted in random places 727-736-1901see incident 11104861\nDuval IT said to use the keys (alt F9)-before uploading the document in the portal to correct the issue.\nHere is the list:\ncode Short description 1 Attorney – Florida Bar 2 Attorney - Pro Hac Vice 3 Attorney – Prosecuting / County 4 Attorney – Internal Counsel for a State Agency 5 Self - Represented Litigant 6 Pro Se/Agent for a Pro Se Litigant 12 Law Firm Administrator 17 Attorney – Assistant US Attorney 23 State Agent 24 Local Agent 25 Creditor 30 Domestic Violence Case Initiator 31 Case Manager"},{"id":"verb-117","title":"Frequently used documents","category":"Verbiage Source","status":"Verify before use","text":"1) Frequently Used Documents are maintained per user as a user preference.\n2) Every document fled from single session (SSC , SSR ) is used in Frequently Used Document Logic. Documents submitted from the System to System interfaces for a given portal user account do not contribute to \"Frequently Used Documents \"\n3) Frequently Used Document logic is based on Portal Docket Code ID. We maintain Portal Docket Code ID and how many times said docket code id is used\n4) We only save/support 100 Frequently Used Documents .\n5) When a filing is submitted from Single Session ( SSC , SSR) and docket code id selected is not already in Frequently Used Document list for said user and # entries in Frequently Used Document list is less than 100 , new entry is added to Frequently Used Document list with selected docket code id and usage count of 1\n6) When a filing is submitted from Single Session ( SSC , SSR) and docket code id selected is not already in Frequently Used Document list for said user and # entries in Frequently Used Document list is 100 , Entry # 100 is replaced list with selected docket code id and usage count of 1\n7) When a filing is submitted from Single Session ( SSC , SSR) and docket code id selected is already in Frequently Used Document list for said user usage count is updated"},{"id":"verb-118","title":"VOR or VOD requests","category":"Verbiage Source","status":"Verify before use","text":"Unfortunately, the e-filing portal website is not the party responsible for the VOR or VOD, as the website is not the clerk of the courts.\nThe e-filing portal does not have the access to send you case documentation.\nPlease contact the Clerk of the Courts in the county your case is filed in for assistance."},{"id":"verb-119","title":"Accessing a case from My Cases to file to the existing case","category":"Verbiage Source","status":"Verify before use","text":"Go to My Cases:\nFind the case and click the 1st SUBMIT button on the left to go to the case:\nLook at the info and scroll down.\nClick next.\nChoose a person from the Current Pary list, scroll down click next.\nClick ADD.\nChose and check the box next to the document type.\nUpload your file.\nClick Save.\nContinue to review each page scroll down and keep on until you click submit at the end."},{"id":"verb-120","title":"Authorized House Counsel","category":"Verbiage Source","status":"Verify before use","text":"Gang, if you are ever asked about \"attorneys\" that are actually Authorized House Counsels- they cannot register as an Attorney of any form. They must register as self reps.\nAn Attorney is a licensed lawyer with broad practice rights, while Authorized House Counsel (AHC) is a lawyer employed exclusively by one company, with limited scope, often licensed elsewhere, and can't represent individuals or generally appear in court, acting as an in-house advisor focused solely on their employer's business needs. The main differences are AHC's single-client focus, restricted practice scope (no court, no outside individuals), and specialized registration, compared to a standard attorney's general licensing and broader client representation.\nAttorney (General)\nClientele: Can represent multiple clients (individuals, businesses, etc.).\nScope: Broad, depending on specialization (e.g., family law, criminal defense, corporate, real estate).\nPractice: Can appear in court, negotiate for clients, offer general advice.\nLicensing: Licensed by a specific state bar, usually requires passing that state's bar exam.\nAuthorized House Counsel (AHC)\nClientele: Only the single business organization that employs them (e.g., a corporation).\nScope: Narrow; provides legal advice only regarding the employer's business and activities.\nPractice: Can draft contracts, handle internal matters, work with agencies, but generally cannot represent the company in court or advise individuals (even officers/directors).\nLicensing: Often lawyers licensed in other states/countries who register with a specific state (like Florida) for limited in-house practice, avoiding full bar exams in the new state.\nKey Distinctions\nSingle Client: AHC serves only their employer; a general attorney serves many.\nLimited Practice: AHC has restrictions (no court, no individuals); general attorneys have broader courtroom and individual representation rights.\nPurpose: AHC facilitates companies bringing legal expertise in-house without needing a full local license for every attorney."},{"id":"verb-121","title":"Locked accounts","category":"Verbiage Source","status":"Verify before use","text":"All- if you come across an account that is lock please run this script BEFORE reactivating it\nselect user_id , sysadmin_notes from user_information where user_id = XXXX\nCurrently there is a bug with the Sys Admin Notes- they disappear from the Profile when you click save. This is schedule to be apart of the next release but they are holding off on deploying the release until the file share issue is addressed- sometime this quarter, hopefully."},{"id":"verb-122","title":"County Specific:","category":"Verbiage Source","status":"Verify before use","text":"This source heading contains no standalone text in the supplied document."},{"id":"verb-123","title":"Brevard:","category":"Verbiage Source","status":"Verify before use","text":"You cannot create the case parties. The Brevard Clerk does this for you by the information you provide on the paperwork you file."},{"id":"verb-124","title":"Broward:","category":"Verbiage Source","status":"Verify before use","text":"Corrections issue:\nError- PDF to TIF message\nThis could be because of the 3rd party vendor for Broward County still has not fixed the issue with the wrong remark going out and the REAL cause is one of the following:\nSomething was wrong with the scan/Document corrupt:\nPaper size, DPI, or color"},{"id":"verb-125","title":"Manatee:","category":"Verbiage Source","status":"Verify before use","text":"Most documents are filed under: Documents(s) for Submission"},{"id":"verb-126","title":"Miami:","category":"Verbiage Source","status":"Verify before use","text":"Notice of Commencement: cannot E-File. Has to have a notarized copy in person or using a 3rd party vendor on the COC website to submit to the county"},{"id":"verb-127","title":"Adding case party to existing- Miami","category":"Verbiage Source","status":"Verify before use","text":"Miami does not allow the addition to the current party's list to an existing case on the e-filing portal website MyFLCOurtAccess.com.\nI would advise them to go ahead and file their paperwork, choosing an attorney or other party from the Current Parties list to be able to get their paperwork filed to the case."},{"id":"verb-128","title":"Summons","category":"Verbiage Source","status":"Verify before use","text":"Has to file and get a case number first:\nhttps://www.miami-dadeclerk.com/library/small_claims/389-Web.pdf\nhttps://www.miami-dadeclerk.com/library/Civil/423-Web.pdf\nEviction Summons\nhttps://www.miami-dadeclerk.com/library/Civil/141-Web.pdf\nhttps://www.miami-dadeclerk.com/library/Civil/314-Web.pdf\nForms for Miami-Dade (at the bottom of their page)\nhttps://www.miami-dadeclerk.com/clerk/civil-family-court.page\nSubpoena- done in person or by mail\nFiling for Expungement: Has to be done in person or by mail:\nhttp://www.sao17.state.fl.us/assets/petition-expunge-packet---jan-2017.pdf\nMiami-Dade 90 Day Medical Malpractice extension- cannot be e-filed, has to be mailed in or done in person\nPetition for Involuntary Placements are filed by medical professionals only.\n10/24/2023 New to note: If an attorney is filing a domestic violence case (not using the DIY) They cannot do it in Miami-Dade. It has to be done in person. See Clerk's website link. https://www.miamidadeclerk.gov/clerk/domestic-violence.page\nMiami-Dade does not allow attorneys to file Domestic Violence cases through the e-filing portal website\nPro-se litigants cannot e-file their new case without the Self-Help Program stamped approval. This means too many things are going on with the filing and it is the clerk’s way of getting the person to come into the clerk's office to resolve it.\nProbate: doc type for checklist isn’t listed, had attorney report that they are using the doc type: Certificate Of Completion / Compliance\nNotice of Sale $70 fee-\nThe $70.00 sale fee and $70.00 electronic fee must by paid by check via mail directly to the Courthouse, these cannot be processed through the e-Portal that’s the reason it was not set up."},{"id":"verb-129","title":"Volusia:","category":"Verbiage Source","status":"Verify before use","text":"Volusia is the only county that does this.\nYou can only enter 1 plaintiff and 1 defendant as parties, but if you list additional parties on your paperwork, the clerk normally reviews the complaint and adds the additional parties for you."},{"id":"verb-130","title":"Lis Pendens:","category":"Verbiage Source","status":"Verify before use","text":"Orange County:\nThere is only a fee if the case is Timeshare related. If it is, the first count is free, all others are $10 each. I believe that is where they would put in the # of Units listed below.\nCircuit Civil, Real Property, Other Real Property"},{"id":"verb-131","title":"Vexatious Litigants:","category":"Verbiage Source","status":"Verify before use","text":"What can we do if there is a court order that says the filer is not to file to the case anymore?\nSearch the filer, open their profile, click Case Restrictions link:\nClick the +:\nEnter required information and click Add:\nIt should look like this:\nThen scroll down to click save:\nFilings over the 50 megabyte limit when the filing cannot be broken down and submitted in multiple pdf files:\nRefer to the clerk on how to get it submitted outside of the portal since the portal is not equipped to send such a large filing to the clerk."},{"id":"verb-132","title":"Multiple Tickets:","category":"Verbiage Source","status":"Verify before use","text":"Hello,\nWe noticed that multiple tickets and messages have been submitted regarding the same issue across different contact channels. To help us assist you as quickly and efficiently as possible, we kindly ask that you please use one communication channel and a single ticket per issue.\nSubmitting multiple tickets or contacting us through several avenues can delay our response time, both for you and for other customers, because it creates duplicate work for our support team.\nPlease be assured that your request is in our queue, and we will respond on ticket #() as soon as possible. Thank you for your patience and for helping us keep support running smoothly."},{"id":"verb-133","title":"TPV: Third Party Vendor information","category":"Verbiage Source","status":"Verify before use","text":"To find information on becoming a Third-Party Vendor, please review the information from the website.\n-\nQuestions: 850-921-0808\nSend to Beth Allman.\nCreate a task assign to self (Beth does not have Ivanti/Task access)"},{"id":"verb-134","title":"Specific case party is not available in list to choose on “Filed On Behalf-Of”","category":"Verbiage Source","status":"Verify before use","text":"Please choose from either the attorney listed or any other party listed, so that you can get your submission to the clerk.\nIt does not matter which person you select as the clerk does not collect that information.\nIf the clerk is going to allow the party to be added to the case, they will insert the party details to the docket."},{"id":"verb-135","title":"100-character limit error message:","category":"Verbiage Source","status":"Verify before use","text":"The error is because of the way your PDF document is named.\nPlease try to keep it at a total of 36 spaces:\nThe name you have given the file is incompatible.\nIf your file has special characters (or exceeds more than 36 total spaces, including blanks) you will need to rename the electronic file.\nExample:\nif it looks like asd_812#.pdf, rename it, removing the unacceptable characters to something else like asd812.pdf"},{"id":"verb-136","title":"Document Sizes:","category":"Verbiage Source","status":"Verify before use","text":"The document sizes are:\nPage size limit: 8.5 x 11\nMegabyte size for all documents combined in a single filing is: 50 MB (absolutely NO exceptions) for all county courts, 200MB for DCA and Florida Supreme Court.\nI cannot tell you how to divide files into separate filings as some clerks are strict about that.\nPlease, the county clerk of courts for their guidelines.\nKeep to the below formatting to keep your MB size down:\nPlease adhere to the following formatting guidelines when filing.\nPlease do not file from a phone or tablet- it may affect functionality.\nYou cannot use the Safari web browser that is on most Apple/Mac devices.\nThe file must be in PDF or PDF/a, or word format. (different for Proposed Orders)\n***NO VIDEOS / NO COLOR PICTURES, NO AUDIO RECORDINGS***\nCall the clerk and ask how to get that to them (format & address to send to)\nThis includes any signatures that are in color- must be black.\nThe page size cannot exceed 8.5 x 11\nIf you are scanning pages into a PDF, make sure they are at 300DPI\nPortal will NOT accept:\nCompressed or zipped files. “Locked” or “Secured” PDF files.\nPDF files names that contain any special or odd characters such as:\nhyphens, underscores, or odd characters (%^&*() =+) or web dings\nPDF file name exceeds 36 characters in length.\nDO NOT SAVE TO THE WORKBENCH TO GO BACK LATER TO RESUME, IT WILL NOT WORK."},{"id":"verb-137","title":"TPV- Third Paty Vendor","category":"Verbiage Source","status":"Verify before use","text":"What is an API?\nAPIs are mechanisms that enable two software components to communicate with each other using a set of definitions and protocols. For example, the weather bureau’s software system contains daily weather data. The weather app on your phone “talks” to this system via APIs and shows you daily weather updates on your phone.\nWhat does API stand for?\nAPI stands for Application Programming Interface. In the context of APIs, the word Application refers to any software with a distinct function. Interface can be thought of as a contract of service between two applications. This contract defines how the two communicate with each other using requests and responses. Their API documentation contains information on how developers are to structure those requests and responses.\nIt's basically an application that links two separate applications together."},{"id":"verb-138","title":"CCIS: Automatic deactivation of their accounts:","category":"Verbiage Source","status":"Verify before use","text":"An email to the gatekeepers is tentatively scheduled to go out on 6/17/2026 to remind them of their \"gatekeeper responsibilities\"-\nMeredith, I let Rankin know that you have several people out on 6/19/2026 and that if you had any questions about this email going out that week or any of these dates that you would reach out to him directly\nAn email to all active users (except FCCC and clerk staff) is tentatively scheduled to go out on 7/6/2026 to remind them CCIS should be used for official use only\nUsers that have not logged into CCIS within a year will be deactivated tentatively on 7/22/2026\nIf the Service Center is contacted by users we should refer them to their gatekeeper, if the gatekeeper is no longer there we need to go through the gatekeeper approval process\nRankin and Seann will generate the list of gatekeepers and provide to Systems\nA list of all deactivated users will be provided to the Service Center to use if we are contacted\nScott asked Rankin if there had been any discussion on automating the deactivation process. Rankin stated the agreement form states we have the authority to deactivate after 6 months of no use- more discussion to happen on this. Scott recommended adding some type of notice to the gatekeepers every time the login to remind them to be responsible gatekeepers- mainly to deactivate users when they leave."},{"id":"verb-139","title":"Email language for potty mouths","category":"Verbiage Source","status":"Verify before use","text":"I want to assure you that I'm here to help and would like to work with you toward a resolution.\nYour recent support tickets were escalated to me due to the tone and language used in the voicemails. I understand that technical issues can be frustrating, and we are committed to assisting our customers, but we do ask that communications remain professional and respectful so that we can work together effectively.\nTo provide some context, our support team consists of nine team members who collectively support more than 900,000 users. Because of this volume, tickets are handled in the order they are received, and we do our best to respond as quickly as possible while ensuring each customer receives appropriate attention.\nWith that in mind, I'd like to focus on resolving the issue you're experiencing. Please let me know the specific assistance you need, and I'll be happy to review the details and determine the best path forward.\nI appreciate your understanding and look forward to helping you\nEditing a service list or removing it from service list:\n**Do not remove unless they have provided proof they have been given allowance to be removed. Usually in the form of a judge signed court order."},{"id":"verb-140","title":"How to enter an appeals case number in the “edit service list” option for removal:","category":"Verbiage Source","status":"Verify before use","text":"Example: 1d-2025-2103\nWould be entered into the search box as 1d2025-2103\ninsert case# 172025CA001729XXXAXA click okay\nfind the person you want to remove:\nToggle buttons to no, and save\nNext 2 steps are crucial: 1. Click save.\nClick okay\nHow to revert to the old version of the website\nYou can revert back to the old version by clicking the double back arrows. The only draw back is, you may have to do this every time you log in.\nYou can also click on your Person icon and make changes to your \"styles\".\nI find that the overlay version is the closest to the old version."},{"id":"verb-141","title":"I need the receipt for filings:","category":"Verbiage Source","status":"Verify before use","text":"Accounts have access to this information if it is within 90 days of todays date.\nGo to the My Account drop down,\nclick on the Email log,\nchange the dates to match the timeline you are looking for,\nDo not use the Type of Email dropdown,\nClick search\nFor receipts, you will be looking for emails that say: Filing Processed.\nPictures are used as only an example (not your case)\nYou can then print out the receipt or download and save it to your computer.\nMotion for Summary Judgement charge $70\nAttorney's being charged for a Motion for Summary Judgement (Example) 251729925 Hillsborough 24-CA-008791 Is there now a $70 fee for this? Per the Clerk I spoke to ...Julie.\nIf the case goes into foreclosure, they (the filer) will need to pay the $70. If the case will not go into a foreclosure, they should not have to pay the $70 If the attorney calls the Hillsborough Clerk say it is not a foreclosure, they can get the $70 refunded back to them.\nEmergency filings\nPlease keep in mind, it is NOT the e-filing portal that uploads your filings to the docket, it is the Clerk of the Courts office.\nIf you have an emergency filing that is \"validating\", always call the clerk first to:\n1. See if there is an issue with the filing.\n2. To see if they could process it quickly if you selected the filing as an emergency option. There is nothing the e-filing website can do to push filings through to the clerk's office.\nMy Cases\nTo find a case that you have filed to via your e-filing portal account:\nDepending on the set up of your portal look. (There are about 5 versions)\nThe steps should be very similar:\nGo to My Cases: You can access from My Account, OR the icon in the upper right corner.\nClick the magnifying glass to open the search options:\nEither search by County or by name. Not both.\nIf you cannot pull it up by name, use the county and look for the court case number.\nTo access the docket (only if you are the attorney of record and the case is not closed, confidential or a formal probate)\nClick on the case number to the far left to access the docket.\nDocket is accessible via the attorney portal account. Sent guidance on how to use the search options."},{"id":"sub-complete-your-registration","title":"Complete your registration","category":"Recovered Source Topic","status":"Verify before use","text":"Complete your registration You will receive a follow-up email that contains a link to activate your account. This email will be sent to the email address that you have registered with The Florida Bar. You must be able to access that account and know the answer to your security question to activate your account. You will receive the account activation email you have registered with The Florida Bar.\nPlease activate your account within 72 hours or it will be deleted from the portal, and you will have to repeat the step to register."},{"id":"sub-confidential-filing","title":"Confidential Filing","category":"Recovered Source Topic","status":"Verify before use","text":"Confidential Filing (should be filed at the time of filing the sensitive information)\nPursuant to Florida Rule of Judicial Administration 2.420(d)(2), the filer of a court record at the time of filing shall indicate whether any confidential information is included within the document being filed; identify the confidentiality provision that applies to the identified information; and identify the precise location of the confidential information within the document being filed."},{"id":"sub-party-names-from-the-financial-id","title":"Party Names from the Financial ID#","category":"Recovered Source Topic","status":"Verify before use","text":"Party Names from the Financial ID#\nYou can look this up by going to My Submissions.\nEnter the EPTL number from your statement: 4229336 into the Financial ID box.\nChange the Submission date to a week before the money was removed from your account.\nYou can go back 90 days from todays date.\nClick search.\nIt should bring up the filing for you to click on and see the case party names."},{"id":"sub-ap-cases-no-summons-option","title":"AP Cases — no Summons option","category":"Recovered Source Topic","status":"Verify before use","text":"AP Cases- no Summons option as of 5/1/2024\nCurrently, the appeals section is not set up to process financial transactions. If the filer wants to use subsequent circuit civil this should allow for the summons to be selected and paid for. Or they can just efile the document under the appeal filing and contact the clerk for payment and issuance."},{"id":"sub-when-escalating-a-ticket-to-the-analyst-team","title":"When escalating a ticket to the Analyst Team","category":"Recovered Source Topic","status":"Verify before use","text":"When escalating a ticket to the Analyst Team (per Gia-teams (3/12/2025)\nThe analysts are tier II support for support specialists. If there is an issue that you all need an analyst to review and assist with, a task should be created. The analyst should then review and if they cannot resolve the issue or have to provide a workaround, the analyst should post in the Service Desk channel. That said, if it is something simple like refund a payment without a filing #, the support specialists can post without having to seek guidance from an analyst. Make sense?"}],"glossary":[{"term":"Ivanti","definition":"Ticket ownership, classification, correspondence, work notes, resolution, and routing."},{"term":"RAC","definition":"Portal administration used for accounts, registration applications, and filing lookup."},{"term":"CCIS","definition":"Court/case information used to verify docket entries, case parties, and attorney-of-record information."},{"term":"TPE","definition":"Payment research system for charges, transactions, and refund investigation."},{"term":"My Submissions","definition":"Portal area showing filings submitted through the account and their Portal status."},{"term":"Workbench","definition":"Saved or in-progress Portal activity. Workbench presence alone does not prove a filing was submitted."},{"term":"Correction Queue","definition":"Portal area used for filings returned for correction."},{"term":"eService","definition":"Electronic service or notice through the Portal. It is not the same as formal service of summons."},{"term":"My Cases","definition":"Cases associated with the Portal account; not a complete official court docket."},{"term":"Filing number","definition":"Portal identifier used to research a submitted filing; distinct from a case number or Workbench item."},{"term":"Cause Code","definition":"Ivanti classification selected at resolution. Exact values are not supplied in the source materials."},{"term":"Analyst task","definition":"Evidence package sent to Analyst or Tier II with identifiers, findings, completed troubleshooting, impact, and requested action."},{"term":"Portal/Clerk boundary","definition":"Portal Support assists with technical submission and navigation; the Clerk controls case processing and the official docket."}],"policyCards":[{"title":"Confidentiality and least-necessary data","text":"Use only job-appropriate information, secure it, and do not place confidential information on insecure devices or public repositories."},{"title":"Hosted-site limitation","text":"This static site has no server-side access control. A public GitHub Pages deployment exposes the application content to the internet."},{"title":"No sensitive ticket data","text":"Do not enter passwords, Social Security numbers, full payment-card or bank-account numbers, credentials, access tokens, or unnecessary customer information."},{"title":"No AI or API","text":"The application uses deterministic JavaScript, fixed source text, regular expressions, and browser memory. It does not call an AI service or application API."},{"title":"Browser-memory behavior","text":"Ticket facts remain in the current browser tab. Only mode, pins, and recent template identifiers may be stored in local browser storage."},{"title":"Current-procedure verification","text":"The trainer stated that some material is repetitive or no longer current. Dated, county-specific, outage-specific, or security-sensitive language must be verified."}]};
